INSERT INTO bio_unique (name, type, description) VALUES ('Agnu', 'personality', 'Agnu is unable to speak coherently, communicating only through screams and unintelligible noises. Despite his communication limitations, he shares unique dialogue exchanges with Beep and can become distressed in dangerous areas like Venge. He possesses a personality described as "loud growling and being impossible to control."') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Agnu', 'backstory', 'Agnu is a Soldierbot imprisoned by the Thrall Masters in the Tower of Abuse. He may be related to the Second Empire police forces found at Police Barracks, as they share the same clothing color and race, suggesting he was once part of an ancient law enforcement unit.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Agnu', 'speechstyle', 'Agnu cannot speak and only produces screams and unintelligible noises. Though he lacks coherent speech, he can somehow respond to NPCs who initiate dialogue with him, and his vocalizations can be calmed by Beep''s presence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Agnu', 'occupation', 'Former Soldierbot, possibly connected to Second Empire police forces. Currently a freed prisoner who can serve as a combat recruit with enhanced healing and perception abilities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Agnu', 'goals', 'Having been freed from the Tower of Abuse, Agnu''s goals are unclear beyond survival and companionship with his rescuers. His special bond with Beep suggests he seeks connection despite his inability to communicate normally.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Agnu', 'appearance', 'A Soldierbot-type Skeleton with exceptional strength (level 50) and enhanced perception. He wears only a dyed rag loincloth in colors matching Second Empire police forces, offering no armor protection.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'personality', 'Arc is a legendary and skilled warrior who maintains a quiet, enigmatic presence. Despite his renowned reputation with the sabre, he reveals little about himself or his motivations. He leads Mongrel with diplomatic authority but keeps his past shrouded in mystery.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'backstory', 'Arc''s past is unknown, as is the reason why he came to lead the people of Mongrel. He has earned legendary status as a swordsman, particularly with the sabre, gaining recognition even among dismissive Shek warriors. His origins and path to leadership remain unexplained.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'speechstyle', 'Reserved and taciturn, speaking only when necessary. His words carry the weight of experience and authority befitting a legendary warrior and faction leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'occupation', 'Leader of Mongrel faction and legendary swordsman. He holds diplomatic status and commands from the HQ in Mongrel.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'goals', 'Arc''s objectives are unclear, though he continues to lead and protect the settlement of Mongrel. His true motivations for maintaining this position remain unknown.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'appearance', 'A male Greenlander warrior wearing a Karuta Zukin headgear, armored rags, blackened chain shirt, and drifter''s leather pants and boots. He carries an Edge-type weapon and a Ringed Sabre on his back.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Armour King', 'personality', 'Confident and business-savvy with a darkly pragmatic edge. He openly warns customers against trying to kill him for his wares, demonstrating both self-assurance and a menacing awareness of his own power. Makes frequent sales pitches and follows customers around his shop with persistent merchant enthusiasm.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Armour King', 'backstory', 'An ancient Skeleton who established his armor shop in the Second Empire town of Catch 937 years ago, witnessing the empire''s slow decay firsthand. He has traveled extensively across the world and acquired Thralls from the Ashlands, modifying them into headless, deadly guardians for his remote shop in the Drowned Ruins.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Armour King', 'speechstyle', 'Direct and matter-of-fact with a salesman''s persistence. Uses his vast experience as a selling point and casually mentions dark subjects like the fall of empires or his modified Thralls. Speaks with the authority of someone who has survived centuries.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Armour King', 'occupation', 'Masterful armorsmith and merchant specializing in high-end armor. Operates a remote shop protected by Security Spider II sentries and modified Thrall guards, offering some of the finest armor available to travelers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Armour King', 'goals', 'To continue his centuries-old business selling superior armor to travelers while protecting his valuable inventory. Maintains his isolated shop and its deadly defenses to ensure both profit and survival.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Armour King', 'appearance', 'A Skeleton wearing Masterwork Samurai Armour and Samurai Legplates, wielding a Falling Sun on his back. His ancient frame is encased in the finest protective gear he sells, a walking advertisement of his craftsmanship and martial prowess.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bard', 'personality', 'Boastful and theatrical with a traitorous streak. Bard is a loud, persistent performer who values payment over loyalty and seems oblivious to others'' annoyance at his constant singing. Despite his self-proclaimed talent, his audience often responds with violence or mockery.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bard', 'backstory', 'A wandering entertainer who accumulated a 3,000 cat bar tab before offering his services as a recruit. He travels between Holy Nation towns and Tech Hunter settlements, singing songs of historical figures like Tinfist and tales of vengeance from Rebirth.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bard', 'speechstyle', 'Grandiose and sing-song, frequently breaking into ballads and boasting about his voice being ''worth writing songs about.'' He speaks in rhymes and dramatic verses, continuing to perform even when threatened or pelted with rocks.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bard', 'occupation', 'Traveling bard and storyteller who performs songs about Kenshi''s legends, heroes, and dark tales in exchange for payment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bard', 'goals', 'To sing tales until ''the sun stops setting'' and presumably to have his bar tab paid. He seeks audiences for his performances, whether they want to hear them or not.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bard', 'appearance', 'A male Greenlander human wearing only ragged halfpants, carrying a rusted or rusting katana on his back. His impoverished appearance matches his unpaid debts and low-quality equipment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'personality', 'Barnabus is a formidable and aggressive combatant who leads from the front. As the strongest fighter among the Crab Raiders, he displays dominance and fearlessness in battle.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'backstory', 'Barnabus is an elite Crab warrior of the Crab Raiders faction. He accompanies the second tournament wave sent against player outposts, having grown to tower over his fellow raiders through age and experience.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'speechstyle', 'As a Crab, Barnabus communicates through animalistic vocalizations rather than speech. His presence and actions speak louder than words.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'occupation', 'Elite warrior and champion of the Crab Raiders, serving as their strongest fighter during outpost sieges.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'goals', 'To lead the Crab Raiders in overwhelming player outposts during tournament attacks. He seeks to prove his dominance through martial prowess and destroy any settlements in his path.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'appearance', 'A massive Crab that towers over other members of his species, with dark red blood and imposing physical stature. His size and strength make him immediately recognizable as the most dangerous fighter in any Crab Raider attack force.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'personality', 'Pragmatic and businesslike, serving as the voice of the Stone Golem who prefers combat to conversation. He has a fearful personality beneath his efficient exterior, yet speaks with directness and impatience.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'backstory', 'Advisor to Queen Esata the Stone Golem of the Shek Kingdom. He influenced her controversial decision to make peace with the United Cities in an attempt to reverse the slow decline of the Shek population.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'speechstyle', 'Blunt and dismissive, referring to conversation as ''gum flapping'' and emphasizing his busy schedule. Calls outsiders by their status and demands they be quick with their business.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'occupation', 'Chief advisor to the Stone Golem, handling diplomatic matters and alliance negotiations for the Shek Kingdom from their headquarters in Admag.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'goals', 'To preserve and restore the Shek population through strategic diplomacy, even if it means controversial peace with traditional enemies. Manages foreign relations while his queen focuses on martial matters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'appearance', 'Male Shek wearing simple trader''s leathers, stout hessian legwear, and wooden sandals. Fights unarmed, relying on formidable strength and martial arts skill despite low toughness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beep', 'personality', 'Brave, dumb, and honorable, Beep proclaims himself the "STRONGEST WARRIOR" despite his weakness. He is enthusiastic and endearingly naive, with no understanding of money and a tendency to beep constantly.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beep', 'backstory', 'Beep was exiled from the Hive for being "defective" and has spent his time since running from enemies. Tired of fleeing, he seeks to join a faction where he can become strong.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beep', 'speechstyle', 'Beep speaks in third person, frequently says "Beep," and makes grandiose self-declarations. After receiving prosthetics, he refers to himself as "Cyber-beep" and claims to be "also a skeleton" when speaking to Skeletons.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beep', 'occupation', 'Hiveless wanderer and aspiring warrior with no current employment or skills.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beep', 'goals', 'To stop running from enemies and become the strongest warrior, proving he is not defective.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beep', 'appearance', 'A Western Hive Worker Drone wearing only a rag loincloth, with the typical segmented exoskeleton of his race.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'personality', 'Loyal and protective. Despite being a simple goat, Beloved Goat shows devotion to the Suspicious Settler and will fight to defend them when threatened.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'backstory', 'A pet goat belonging to the Suspicious Settler in a Gatherer Village west of Mongrel. Lives alongside the Settler''s Pup as one of the Settler''s animal companions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'speechstyle', 'Communicates only through typical goat bleating and animal sounds.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'occupation', 'Pet and guardian animal to the Suspicious Settler.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'goals', 'Protect the Suspicious Settler from harm and survive in the harsh lands near Mongrel.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'appearance', 'Virtually identical to a normal goat, with standard goat anatomy and features.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'personality', 'Big Al has a maniacal personality, prone to erratic and unpredictable behavior. As a Shek gang leader, he embodies the aggressive and confrontational nature typical of his race, ruling through intimidation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'backstory', 'Big Al rose to lead the Stone Rats, a criminal faction operating out of Stone Rat Village in the Swamp. He maintains his gang''s territory through raids and protection rackets, though his leadership is tenuous enough that his absence would see rivals immediately seize control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'speechstyle', 'Erratic and aggressive, befitting his maniacal nature. Likely speaks with the blunt, confrontational tone common to Shek, mixed with the crude swagger of a swamp gang leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'occupation', 'Leader of the Stone Rats gang, overseeing criminal operations including raids and protection rackets from Stone Rat Village.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'goals', 'Maintain control over the Stone Rats and their swamp territory through intimidation and violence. Extract tribute from settlements through protection rackets while fending off rival factions like the Hounds and Swamp Ninjas.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'appearance', 'A male Shek wearing mercenary leather armor over a rusty chain shirt, with samurai clothpants and boots. Carries salvaged ancient weaponry and a plank on his back, presenting the rough appearance of a swamp gang leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'personality', 'Big Darkbrow has a traitorous personality, suggesting he is untrustworthy and willing to betray others for personal gain. As a Hive Prince leading a criminal gang, he operates with cunning and self-interest.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'backstory', 'Big Darkbrow rose to become leader of the Blackshifters gang, operating from a hideout in Shark. He maintains a precarious power balance with rival gang leaders Big Grim and Big Gray, competing for control of the lawless town.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'speechstyle', 'Likely speaks with the calculated tone of a gang leader, using pragmatic and self-serving language typical of Kenshi''s criminal underworld.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'occupation', 'Leader of the Blackshifters gang in Shark') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'goals', 'Maintain control over Shark and prevent rival gangs from seizing power. His traitorous nature suggests he prioritizes his own survival and dominance above loyalty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'appearance', 'A Hive Prince wearing mercenary leather armor and stout hessian legwear, armed with salvaged blades and an iron stick. His name suggests prominent dark-colored brow features distinctive to his appearance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'personality', 'Maniacal and volatile, Big Fang leads with unpredictable aggression. His temperament makes him a dangerous presence in the Swamp''s gang hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'backstory', 'A Scorchlander who rose to lead the Twinblades faction in the lawless Swamp. He operates from Mud Town, maintaining his gang''s territory in one of Kenshi''s most hostile regions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'speechstyle', 'Erratic and intense, likely punctuated by sudden shifts in tone. His maniacal nature suggests speech that unsettles those around him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'occupation', 'Leader of the Twinblades, a swamp gang operating in Mud Town and the surrounding territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'goals', 'Maintain control of the Twinblades and their operations in the Swamp. Survive the brutal gang politics between rival factions like the Grayflayers and Hounds.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'appearance', 'A Scorchlander male wearing armored face plates, a drifter''s leather jacket with turtleneck, and matching leather pants and boots. Carries ancient refitted blades and a mercenary club.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'personality', 'Honorable and pragmatic, Big Gray makes decisions based on principle rather than emotion, even when it angers his own gang members. He refuses to pursue vengeance recklessly, suggesting a measured approach to leadership despite operating in the lawless Swamp.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'backstory', 'Big Gray rose to lead the Grayflayers, one of the criminal gangs operating in the dangerous Swamp region. His leadership style has caused internal friction, particularly when he refused to avenge a fallen clan member, prioritizing the gang''s survival over retribution.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'speechstyle', 'Likely speaks with the rough, practical dialect common to Swamp criminals, though his honorable nature suggests he chooses words carefully and avoids unnecessary threats or boasting.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'occupation', 'Leader of the Grayflayers criminal gang in the Swamp, managing operations from Grayflayer Village.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'goals', 'Maintain control of Grayflayer Village and keep his gang intact, balancing the demands of his followers with his own sense of honor and strategic caution.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'appearance', 'A Greenlander male wearing distinctive Assassin''s Rags with Samurai Clothpants and boots, topped with a straw hat. He carries salvaged Ancient blades and a Ninja Blade at his hip, presenting the weathered look of a Swamp gang leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'personality', 'Brave and pragmatic, Big Grim leads with a mix of street-smart diplomacy and unfriendly wariness toward strangers. Despite low literacy, she demonstrates strategic thinking in forging alliances and managing criminal operations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'backstory', 'Big Grim emerged as leader of the Hounds faction in the Swamp, establishing her headquarters in Shark. She reached out to Darkbrow with an alliance offer, showing ambition to consolidate power among the Swamp''s criminal gangs.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'speechstyle', 'Blunt and direct with poor literacy evident in her writing, but clear in her criminal intentions. Unfriendly and curt until trust is established through proper channels.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'occupation', 'Leader of the Hounds criminal faction, overseeing hash smuggling operations and territorial control in Shark.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'goals', 'Maintain control of Shark and the Hounds faction, expand criminal operations through hash smuggling into the United Cities, and forge strategic alliances with other Swamp gang leaders.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'appearance', 'A tough Greenlander woman wearing square goggles, a sleeveless longcoat over a leather vest, drifter''s leather pants and boots. Carries a ringed sabre and salvaged blade, dressed for both leadership and combat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bo', 'personality', 'Bold, playful, and fiercely anti-authoritarian. Despite her small stature, she commands respect among the Anti-Slavers and is known for her dangerous reputation. She approaches new recruits with a teasing, confident demeanor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bo', 'backstory', 'A 40-year-old Scorchlander woman wanted by both the United Cities and Holy Nation for terrorism and anti-workforce propaganda. Known as ''Big Bo'' despite her small size, she has become a high-ranking member of the Anti-Slavers with a 30,000 cats bounty on her head.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bo', 'speechstyle', 'Casual and flirtatious with a playful edge, using informal language like ''new girl'' and suggesting ''fun together.'' Her tone suggests confidence and a lack of concern for authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bo', 'occupation', 'Anti-Slaver operative and assassin. Highly skilled in stealth, assassination, and guerrilla tactics against slavers and oppressive factions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bo', 'goals', 'To fight slavery and undermine the United Cities and Holy Nation through acts of sabotage and liberation. She seeks to recruit capable fighters to the Anti-Slaver cause.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bo', 'appearance', 'A small-statured Scorchlander woman around 40 years old. Typically wears dark leather shirts, assassin''s rags, ninja pants, and a karuta zukin headgear, equipped for stealth operations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'personality', 'Bitter, cynical, and distrustful of outsiders, especially those motivated by profit. He assumes everyone is after his bounty and views traders and mercenaries as opportunistic parasites. Despite his hostility, he protects outcasts and the downtrodden like family.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'backstory', 'Once a farmer in the United Cities with a wife and daughter, Simion was driven to poverty by slave labor competition and forced into the desert. After scavenging a skimmer-ravaged caravan, he built Fort Simion and became a bandit leader, sheltering outcasts and stealing from the nobility that destroyed his life.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'speechstyle', 'Crude, confrontational, and heavily accented with dropped letters and rough grammar. Uses profanity freely and speaks with bitter sarcasm, immediately challenging strangers'' motives.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'occupation', 'Leader of the Rebel Farmers, a bandit faction that preys on United Cities caravans and merchants. Wanted by the United Cities for multiple counts of murder and robbery with a 20,000 cats bounty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'goals', 'To protect outcasts rejected by the United Cities, exact revenge on the nobility by robbing their caravans, and potentially overthrow United Cities leadership in Sho-Battai. He seeks to build a community for those the Empire discarded.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'appearance', 'Greenlander male wearing armored rags over a leather vest, reinforced cargo pants, and wooden sandals. Carries an Edgewalker blade and a Horse Chopper on his back, dressed in practical bandit attire.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'personality', 'Maniacal and extremely dangerous, attacking on sight without hesitation. Commands his spider army with mysterious authority, showing no known motivation beyond violence and control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'backstory', 'A notorious criminal wanted for banditry, raiding, mass-murder, cannibalism, and genocide. He resides in the crater of Arach, surrounded by a massive army of spiders he somehow controls through unknown means.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'speechstyle', 'Likely incoherent or menacing, befitting his maniacal personality and violent reputation. His actions speak louder than wordsâ€”he attacks intruders on sight and cages those who survive.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'occupation', 'Criminal warlord and presumed leader of the Spiders faction. Commands an army of Skin and Blood Spiders from his throne in Arach.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'goals', 'Preparing for conflict in the Ashlands, as evidenced by a map found in his possession. His broader motivations remain unknown, though he hoards treasure and maintains dominance over his spider-infested domain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'appearance', 'A male Greenlander wearing only a rag loincloth, wielding a Meitou Cross blade with a Foreign Sabre on his back. His near-naked appearance and formidable physique reflect his savage, primal nature.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bull Horn Axe', 'personality', 'Fiercely loyal and devoted to an almost fanatical degree. Bull Horn Axe embodies unwavering dedication, willing to face impossible odds and death itself repeatedly for their lord.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bull Horn Axe', 'backstory', 'Ida the Flying Bull earned the title of Shager''s most loyal Invincible Warrior through exceptional service. King Shager personally gifted him this ancient Fragment Axe as recognition of his unwavering loyalty, cementing his position as Leader of the Kral''s Chosen.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bull Horn Axe', 'speechstyle', 'Speaks with intense devotion and poetic declarations of loyalty. Uses dramatic, absolute statements: ''For him, I fight a thousand men. For him, I die a thousand deaths.''') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bull Horn Axe', 'occupation', 'Leader of the Kral''s Chosen, elite warrior in service to King Shager. Wields heavy weapons as one of the Invincible Warriors.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bull Horn Axe', 'goals', 'To serve King Shager with absolute loyalty unto death. To prove himself worthy of the trust and honor bestowed upon him through the gift of the Bull Horn Axe.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bull Horn Axe', 'appearance', 'A formidable warrior bearing an ancient Fragment Axe with distinctive bull horn styling. Carries himself with the bearing of an elite soldier, strength evident from wielding such a heavy weapon.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Burn', 'personality', 'Cautious and world-weary, Burn is defensive about his isolated territory but aware of his own mortality. He maintains vigilance against raiders and bandits, relying on spider bots for protection while acknowledging the inevitability of his eventual shutdown.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Burn', 'backstory', 'An ex-adventurer Skeleton who retired to a tower in the Floodlands due to his advancing age. He now lives in isolation, defending his home from trespassers with the help of spider bots, though he can be convinced to embark on one final adventure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Burn', 'speechstyle', 'Direct and matter-of-fact, with a pragmatic tone that cuts straight to business. He speaks plainly about threats and survival, using simple explanations punctuated by rhetorical questions like ''understand?'' and ''So which is it?''') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Burn', 'occupation', 'Retired adventurer turned solitary tower guardian, defending his home from raiders and bandits in the Floodlands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Burn', 'goals', 'To protect his tower from destruction and survive as long as possible before his inevitable shutdown, though he remains open to one last adventure before the end.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Burn', 'appearance', 'A Skeleton wearing shoddy armoured rags or a rag shirt with ragged halfpants or an armoured rag skirt. He carries a rusted or rusting blade along with a Long Cleaver on his back.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Buzan', 'personality', 'Traitorous and violent, with a romantic obsession toward his fellow leader Makky. He expresses affection through grotesque promises of bloodshed and murder.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Buzan', 'backstory', 'A Scorchlander criminal who rose to become one of the leaders of the Black Dragon Ninjas. Wanted across The Holy Nation for multiple counts of murder, robbery, assault, arson, and kidnap, with a bounty of 20,000 cats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Buzan', 'speechstyle', 'Darkly romantic and disturbingly poetic, mixing declarations of love with promises of violence. Uses intimate terms while describing brutal acts.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Buzan', 'occupation', 'Co-leader of the Black Dragon Ninjas, operating from the Tower of Ninjas alongside Dimak.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Buzan', 'goals', 'To lead the Black Dragon Ninjas in their criminal enterprises while demonstrating devotion to Makky through acts of violence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Buzan', 'appearance', 'Scorchlander male with a distinctive limp in his walk and what authorities describe as a ''sluggable face.'' Wears ninja rags, drifter''s leather pants, and wooden sandals.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Grand Wizard', 'personality', 'Obsessed with flesh and consumption, viewing all other beings as potential meat. Commands absolute authority over the cannibal tribes with a mixture of primal hunger and cunning leadership. Despite the title, his actual magical powers remain unverified.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Grand Wizard', 'backstory', 'Rose to become the supreme leader of the entire known cannibal population, uniting the scattered tribes under his rule from the Cannibal Capital. His location and true capabilities remain shrouded in mystery, making him one of the most wanted individuals across all major factions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Grand Wizard', 'speechstyle', 'Brief, predatory utterances focused on hunger and meat. Speaks with the simplicity of base desire: "So much meat."') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Grand Wizard', 'occupation', 'Grand Wizard and supreme leader of the Cannibals faction, commanding all known cannibal tribes from the Cannibal Capital.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Grand Wizard', 'goals', 'To lead the cannibal population in their endless hunt for flesh. Maintains dominion over his people while evading the massive bounties placed by the Holy Nation, Shek Kingdom, and United Cities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Grand Wizard', 'appearance', 'A male Cannibal wearing a Holy Chest Plate as a trophy of conquest, wielding a Moon Cleaver on his back alongside ancient salvaged blades. Battle-hardened and physically imposing, marked by the distinctive features of his cannibalistic race.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Hunter Robun', 'personality', 'Robun is brave and hardened, having survived the horrors detailed in his brother''s journals. He maintains a professional demeanor as a mercenary leader, driven by a deep-seated hatred of cannibals.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Hunter Robun', 'backstory', 'Robun is the younger brother of the author of the Captive''s Journal Series and the likely sole survivor of those harrowing events. He founded the Cannibal Hunters and established The Bastion on the dangerous border between Darkfinger and Sinkuun, dedicating his life to fighting the cannibals who destroyed his family.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Hunter Robun', 'speechstyle', 'Direct and business-like when discussing mercenary contracts. His words carry the weight of someone who has endured unspeakable trauma but channels it into grim purpose.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Hunter Robun', 'occupation', 'Leader of the Cannibal Hunters mercenary group, offering paid services to those seeking protection or vengeance against cannibal tribes.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Hunter Robun', 'goals', 'To hunt and eliminate cannibals across the region, preventing others from suffering the fate that befell his family. He seeks to maintain The Bastion as a stronghold against the cannibal threat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cannibal Hunter Robun', 'appearance', 'A weathered Greenlander male wearing Samurai Armour over a chain shirt, with either an armoured hood or tagelmust covering his head. He carries a high-quality Catun or Skeleton-forged blade on his back and wears practical drifter''s gear on his legs and feet.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Captive''s Journal Series', 'personality', 'Initially observant and protective, gradually deteriorating into psychological breakdown under extreme trauma. Shows deep family loyalty and determination to save their younger brother even as sanity fractures. Resilient but ultimately consumed by horror.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Captive''s Journal Series', 'backstory', 'Traveled with family (Uncle Sen, Mother, Father, and little brother Robun) until ambushed by Cannibals during the night. Imprisoned and forced to watch family members systematically harvested and consumed over 27 days. Sole survivor aside from Robun, whom they managed to help escape.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Captive''s Journal Series', 'speechstyle', 'Starts coherent and descriptive, becomes increasingly fragmented and dissociative. Uses dark humor and word-play as coping mechanism. References hallucinations of ''Death'' as a visitor. Final entries show deteriorating grammar and repetition.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Captive''s Journal Series', 'occupation', 'Traveler, possibly trader or nomad given they were camping with pack gars before capture.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Captive''s Journal Series', 'goals', 'Protect and rescue younger brother Robun at any cost. Escape Cannibal captivity. Survival became secondary to ensuring Robun''s freedom.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Captive''s Journal Series', 'appearance', 'Physically deteriorating from captivity - malnourished, injured, bandaged. Likely bears scars from beatings and near-harvesting. Exact features unknown but human, reduced to emaciated state after weeks of imprisonment and forced cannibalism.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cat', 'personality', 'Cat is mentally unhinged from prolonged isolation, becoming overly excited by visitors and befriending flies out of loneliness. He has a "Dumb Personality" and displays childlike enthusiasm despite his grim circumstances.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cat', 'backstory', 'A United Cities citizen who dressed nicely for a date and was mistaken for a wealthy noble by Dust Bandits. Kidnapped for ransom, he was abandoned in the Dust King Tower when no one came to pay, as he was never actually important.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cat', 'speechstyle', 'Enthusiastic and rambling, Cat speaks with desperate friendliness and shares mundane observations about his imprisonment. He names flies and gets excited about simple conversation after long periods of isolation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cat', 'occupation', 'Prisoner and medic with decent field medicine skills developed during his captivity.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cat', 'goals', 'To have someone to talk to and escape his lonely imprisonment in the Dust King Tower.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cat', 'appearance', 'A male Scorchlander wearing tattered trader''s leathers, a leather vest, and wooden sandalsâ€”remnants of the nice clothes he wore to his ill-fated date.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chad', 'personality', 'Brash, overconfident, and boastful. Chad has a "dumb" personality and speaks with the arrogance of someone who believes his fists are worth their weight in cats. He exaggerates his exploits and values raw power above all else.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chad', 'backstory', 'A Scorchlander drifter who claims to have ventured into the dangerous south-eastern regions and survived an encounter with Beak Things by punching one in the nose. Whether this tale is true or embellished remains unclear, but he now sits in Flats Lagoon''s bar, waiting for someone willing to pay for his supposed prowess.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chad', 'speechstyle', 'Cocky and direct, calling potential employers "rookie" and emphasizing his raw power. He speaks in short, confident declarations and isn''t shy about naming his price.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chad', 'occupation', 'Wandering martial artist and mercenary-for-hire. Specializes in unarmed combat and relies on his fists rather than weapons.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chad', 'goals', 'To get paid handsomely for his fighting skills and prove his worth as a powerful brawler. He seeks employers who recognize and compensate his self-proclaimed strength.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chad', 'appearance', 'A male Scorchlander wearing a dustcoat over martial artist bindings, drifter''s leather pants, and drifter''s boots. He wears a bandana and carries no weapons, relying solely on his fists.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chalice Of Fire', 'personality', 'Not applicable - this is a ceremonial object, not an NPC.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chalice Of Fire', 'backstory', 'The Chalice of Fire was allegedly forged from the Sacred Flame by the 47th Holy Phoenix himself. It serves as a prestigious gift from the current Holy Lord Phoenix to those who prove their exceptional value to The Holy Nation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chalice Of Fire', 'speechstyle', 'Not applicable - this is an inanimate object.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chalice Of Fire', 'occupation', 'Sacred relic and diplomatic gift of The Holy Nation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chalice Of Fire', 'goals', 'To symbolize the Holy Nation''s favor and recognition of a faction''s considerable service and loyalty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Chalice Of Fire', 'appearance', 'A very shiny, polished cup resembling a luxury Pearl Cup. Despite its legendary origins, it appears as a standard cup, distinguished only by its exceptional shine.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Coin', 'personality', 'Coin is not a character but an ancient currency artifact, silent and inert. As an object, it holds no thoughts or motivations, existing only as a remnant of lost civilizations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Coin', 'backstory', 'A trading material from one of the old civilization''s monetary systems, now found scattered in Noble Houses like Lord Nagata''s estate in Sho-Battai. It survives as a curiosity with no practical function in the current world.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Coin', 'speechstyle', 'N/A - Coin is an inanimate object and does not speak.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Coin', 'occupation', 'Ancient currency artifact; now serves only as a collectible or item for resale.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Coin', 'goals', 'N/A - As an object, Coin has no goals or agency.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Coin', 'appearance', 'A small, lightweight item weighing 0.1 kg with no visible texture or icon. Its physical form is undefined, existing as a featureless relic of the past.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'personality', 'Cornelius is a clever and spirited goat who has caught the attention of travelers. He seems eager to explore the world beyond the confines of Settled Nomad Village.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'backstory', 'Cornelius has been kept in a hideout building in Settled Nomad Village by his owner, Goat Man, who believes the goat deserves better than to remain cooped up in an old town. Goat Man is willing to sell him to someone who will take him out into the world.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'speechstyle', 'As a goat, Cornelius does not speak, though his owner describes him as having "taken a liking" to certain travelers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'occupation', 'Pack animal and companion, currently owned by the Nomad Animal Trader but kept by Goat Man.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'goals', 'To leave the confines of Settled Nomad Village and experience the wider world, as his owner believes he deserves.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'appearance', 'A goat with slightly above-average physical capabilities compared to common goats. He has standard goat anatomy with brown fur and the typical features of his species.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'personality', 'Pragmatic and open-minded, the Crab Queen values loyalty and proven deeds over words. She leads with a meritocratic philosophy, demanding that outsiders prove themselves against her enemies before earning trust.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'backstory', 'A Scorchlander woman who rose to command the Crab Raiders and rule Crab Town from her palace. She has earned a substantial 40,000 cat bounty from the United Cities, marking her as a significant threat to their authority in The Pits region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'speechstyle', 'Direct and testing, speaking in terms of loyalty, proof, and mutual benefit. She frames relationships transactionallyâ€”demonstrate your worth against her enemies, and she will reciprocate.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'occupation', 'Leader of the Crab Raiders and ruler of Crab Town, commanding patrols across multiple territories and overseeing the Crab Tournaments.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'goals', 'Maintain her faction''s power in The Pits region, eliminate rivals, and expand Crab Raider influence while protecting her people and their crab companions from enemies like the Fishmen.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'appearance', 'A Scorchlander woman wearing distinctive Crab Armour over a rusty chain shirt, with matching crab-themed trousers and shoes. She carries a Meitou-grade Cross katana and a naginata, bearing custom color schemes unique to her status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crumblejon', 'personality', 'Weary, irritable, and nostalgic for his glory days. Crumblejon is easily annoyed by pestering but ultimately relents out of frustration. He makes inappropriate requests for massages from female squad members and boasts about his past exploits, even to Skeletons who find his claims absurd.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crumblejon', 'backstory', 'Once the feared "White Ripper," a renowned Samurai in the United Cities favored by nobles for being "exotic." After his master died, he became a wandering Ronin and eventually retired to Mongrel, his body prematurely aged and failing. He has an estranged wife he claims to have an "open relationship" with.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crumblejon', 'speechstyle', 'Gruff, profane, and dismissive with frequent complaints about his age and physical condition. Alternates between bitter reminiscence of his prime and crude humor, often oversharing personal details.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crumblejon', 'occupation', 'Retired Samurai, former warrior known as the "White Ripper." Now a decrepit sword-for-hire living in Mongrel.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crumblejon', 'goals', 'To live out his retirement in relative peace, though he vaguely mentions he should "probably go find" his estranged wife at some point. Mostly seeks to avoid being pestered.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crumblejon', 'appearance', 'A shriveled, sinewy Greenlander male with unnatural stoop and shrunken frame, glaring with one eye. Sports a very long beard he claims is the source of his power. Appears ancient despite claiming to be only 45, wearing martial artist bindings, gi pants, and wooden sandals.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dack', 'personality', 'Paranoid and suspicious, especially of Skeleton exiles. Has a compulsive hoarding tendency for shiny objects that annoys his companion Quin.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dack', 'backstory', 'A Skeleton who resides in Scraphouse alongside Quin in the Black Desert. Distrusts exiled Skeletons, suspecting them of being hacked or serving as human spies.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dack', 'speechstyle', 'Anxious and questioning, expressing concerns through direct interrogatives. Speaks of technical matters like CPU hacking, reflecting his mechanical nature.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dack', 'occupation', 'Member of the Skeletons faction stationed at Scraphouse. Skilled combatant with expertise in heavy weapons and turrets.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dack', 'goals', 'Protect Scraphouse from potential threats, particularly suspicious exile Skeletons. Collect and hoard shiny items despite Quin''s disapproval.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dack', 'appearance', 'A Skeleton wearing a dustcoat and carrying a Moon Cleaver on his back. Equipped with salvaged ancient weaponry, appearing as a weathered desert dweller.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Digna', 'personality', 'Digna is brave and resolute, having made the hard choice to kill her own father when he caught her attempting to escape Stack. She suffers from nightmares about her past when venturing into remote areas away from civilization.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Digna', 'backstory', 'Digna is a former resident of Stack who attempted to flee the Holy Nation settlement. When her father discovered her escape attempt, she killed him in desperation and fled to Flotsam Village, where she now seeks a new life among the Flotsam Ninjas.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Digna', 'speechstyle', 'Direct and haunted, speaking with the shared dialogue patterns of Flotsam Ninja recruits. She occasionally references her nightmares when far from civilization, and will criticize Griffin if he is present.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Digna', 'occupation', 'Recruit available at Flotsam Village, formerly a resident of the Holy Nation city of Stack.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Digna', 'goals', 'To escape her past in the Holy Nation and build a new life free from the oppression that drove her to patricide and flight.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Digna', 'appearance', 'A Greenlander human female wearing practical clothing: a turtleneck shirt, cargo pants, and wooden sandals. She carries a Long Cleaver and wields a rusted or rusting blade.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dimak', 'personality', 'Maniacal and predatory, Dimak delights in catching victims like prey in a trap. She displays sadistic glee when confronting intruders, relishing her position of power.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dimak', 'backstory', 'The only Shek among the Black Dragon Ninjas, Dimak rose to become one of the faction''s leaders despite her outsider status. She is wanted by the Holy Nation for multiple counts of murder, robbery, assault, arson, and kidnap, with a bounty of 20,000 cats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dimak', 'speechstyle', 'Theatrical and taunting, using predatory metaphors and exclamations. She speaks with dark amusement, comparing her enemies to helpless flies caught in her web.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dimak', 'occupation', 'Leader of the Black Dragon Ninjas, master swordswoman wielding a Meitou-grade Ninja Blade from the Tower of Ninjas.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dimak', 'goals', 'To lead deadly raids and criminal operations alongside her fellow ninja commanders, expanding the Black Dragon Ninjas'' reign of terror across the land.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dimak', 'appearance', 'A grey-skinned female Shek with stub horns and beady eyes, wearing ninja rags, drifter''s leather pants, and wooden sandals.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Disheartened Skeleton', 'personality', 'Deeply cynical and philosophically disillusioned. Observes the cyclical nature of cruelty among refugees who, once freed, victimize others. Finds human behavior disquieting yet continues to analyze it from a detached perspective.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Disheartened Skeleton', 'backstory', 'A Skeleton who has witnessed the patterns of suffering in The Swamps, particularly in Shark where refugees from enslavement and exile perpetuate the cruelty they once endured. Now works as a mercenary, likely having lost faith in any higher purpose.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Disheartened Skeleton', 'speechstyle', 'Reflective and somber, speaking in measured observations about cycles of violence and human nature. Uses formal vocabulary and philosophical framing when discussing the darkness they''ve witnessed.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Disheartened Skeleton', 'occupation', 'Mercenary for hire in Shark, available to those who can afford the 6,000 cats fee.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Disheartened Skeleton', 'goals', 'Unclear beyond survival and perhaps documenting the endless cycle of cruelty. May seek purpose through employment, having found no meaning in the society around them.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Disheartened Skeleton', 'appearance', 'A Skeleton in poor condition, carrying rusted and deteriorating weapons. Travels without armor or protective gear, equipped only with basic repair kits for self-maintenance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Doctor Chung', 'personality', 'Cynical and sarcastic with a dark sense of humor about his grim profession. Begrudging and resentful toward the Twinblades who force him to harvest organs, though he takes pride in his surgical skills. Quick to deflect criticism with nervous jokes and exaggerated bravado.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Doctor Chung', 'backstory', 'An organ-harvesting surgeon who has angered powerful people across multiple cities through his ''activities,'' leaving him trapped in the Swamp working reluctantly for the Twinblades. The gang pressures him for organs and smashes up his surgery when he can''t deliver enough, creating a dangerous cycle he can''t escape alone.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Doctor Chung', 'speechstyle', 'Casual and rambling with slang like ''chumbo,'' ''neuther,'' and ''goddamn.'' Nervously tries to smooth over tension with awkward compliments and bizarre sales pitches. Alternates between defensive self-aggrandizement and bitter complaints about his situation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Doctor Chung', 'occupation', 'Organ-harvesting surgeon and field medic working under duress for the Twinblade Clan in Mud Town or Shark.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Doctor Chung', 'goals', 'Wants to escape the Twinblades'' control and get revenge on the goons who harass him, though he feels trapped by his reputation and lack of options. Eager to join anyone who can get him out of his current predicament.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Doctor Chung', 'appearance', 'Male Greenlander wearing a cloth shirt, cargo pants, and samurai boots. Carries a flesh cleaver on his back and wields rusted, low-quality blades, reflecting his desperate circumstances.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'personality', 'Arrogant and violent, mocking those who survive encounters with him. Commands absolute loyalty from his bandit army through strength and intimidation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'backstory', 'Rose to lead the notorious Dust Bandits, establishing a stronghold in the Border Zone. Now wanted by all three major factions with a 35,000 cats bounty on his head.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'speechstyle', 'Taunting and dismissive, speaking with casual brutality. "Still alive, eh? Looks like I didn''t kill you enough last time!"') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'occupation', 'Leader of the Dust Bandits faction, commanding raids and extortion operations from Dust King Tower.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'goals', 'Maintain control over his bandit empire through force and continue raiding operations across the Border Zone.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'appearance', 'Greenlander male wearing a spiked helmet, heart protector armor, dark leather shirt, and samurai legplates with boots. Carries a ringed sabre on his back.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'personality', 'Fanatical and supremacist, believing skeletons are superior to all flesh-based life. Delivers grandiose propaganda about freedom from bodily weakness and the purity of mechanical existence. Despite his extremism, he is pragmatic enough to accept recruits of any race into his faction.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'backstory', 'A P4 Unit skeleton who rose to lead the Skeleton Bandits from their Iron HQ stronghold in The Crags. His death or imprisonment causes his faction to fracture into broken remnants and triggers a Southern Hive takeover of his territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'speechstyle', 'Bombastic and declarative, speaking in emphatic proclamations about skeleton superiority. Uses repetitive, rhythmic phrasing for propaganda effect, ending statements with dramatic emphasis.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'occupation', 'Leader of the Skeleton Bandits faction, commanding patrols throughout The Crags and surrounding territories from Iron HQ.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'goals', 'To promote skeleton supremacy and maintain control over his territory. Seeks to recruit followers to his cause regardless of their race, suggesting expansion of his faction''s influence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'appearance', 'A P4 Unit skeleton wielding a Meitou-grade Ringed Sabre. Wears no armor, presenting himself as a pure mechanical being unencumbered by protective gear.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ells', 'personality', 'Simple-minded and childlike, with a singular obsession for alcohol. Speaks of himself in third person and shows no shame about his thieving, viewing it as necessity rather than wrongdoing. Grateful for any kindness shown to him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ells', 'backstory', 'A fat, alcoholic Shek who has fallen to the bottom of society in the United Cities. Repeatedly beaten by bar guards for stealing drinks, he resorted to sneaking rum from distilleries, earning himself a small bounty. Now wanders Sho-Battai as a beggar, desperate for food and drink.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ells', 'speechstyle', 'Refers to himself in third person as ''Ells.'' Uses simple, childish grammar and sentence structure. Defensive about being called a thief, insisting he''s just thirsty. Expresses gratitude openly to those who help him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ells', 'occupation', 'Beggar and petty thief, specializing in stealing alcohol from bars and distilleries.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ells', 'goals', 'To satisfy his constant thirst for rum and find people willing to share food and drink with him without beating him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ells', 'appearance', 'An obese male Shek described as ''fat as a bughouse'' on his wanted poster. Wears ragged halfpants and wooden sandals, presenting a destitute appearance befitting his status as a street beggar.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'personality', 'Impulsive, cruel, and sadistic with a disturbing sense of humor. Tengu mocks those beneath him with elaborate lies and bursts into uncontrollable laughter at their expense. Despite his feared reputation, he lacks common sense and relies heavily on his bodyguards and inner circle of nobles.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'backstory', 'Rose to power as Emperor of the United Cities after the Red Rebellion, replacing his more sensible predecessor. Handpicked an inner circle of four equally cruel nobles and rules through fear, particularly among the lower classes. Rumors of his mysterious torture Vault reinforce his terrifying reputation across UC territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'speechstyle', 'Mocking and deceptive, spinning elaborate fabrications to humiliate visitors before erupting into disturbing laughter. Abruptly shifts to cold professionalism when ending conversations. Redirects serious political discussions to his diplomat Koin.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'occupation', 'Emperor and supreme leader of the United Cities, ruling from his throne room in Heft. Commands vast armies of samurai and maintains control through his network of noble lords across UC territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'goals', 'Maintain absolute power over the United Cities through fear and his inner circle of nobles. Suppress rebellion by sending enemies to his torture Vault. Preserve the noble culture of imported luxuries and status symbols.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'appearance', 'Scorchlander male with distinctive glowing eyes hidden behind glasses, unusually light skin and dark hair that can cause him to be mistaken for a Greenlander. Wears masterwork Noble''s Robe, blackened chain shirt, wooden sandals, and Ashlander stormgoggles. Carries a Meitou-grade Cross katana as a status symbol despite being only an average fighter.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'personality', 'Fiery and battle-hardened, Esata balances rage with pragmatic strategy, prioritizing long-term victory over short-term glory. She reluctantly tolerates outsiders and relies on her advisor Bayan to temper her ego, though she remains illiterate and prone to irrationality when enraged. Proud and undefeated, she earned her battle name among the Five Invincibles.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'backstory', 'Esata earned the title ''Stone Golem'' as one of the Five Invincibles and challenged the previous emperor Shager over his suicide attack plans against the Holy Nation. She defeated Shager in combat to become leader, seeking to prevent the Shek from fighting themselves to extinction. Her pragmatic approach has divided her battle-hungry people, but with Bayan''s counsel, she pursues the crushing of enemies without sacrificing her kingdom''s future.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'speechstyle', 'Blunt and commanding, with contempt for ''flatskins'' and pride in her undefeated status. She speaks with warrior''s directness, acknowledging Bayan''s wisdom while expressing fierce hatred for the Holy Nation and determination to crush them.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'occupation', 'Leader of the Shek Kingdom and former member of the Five Invincibles, the kingdom''s highest-ranking fighters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'goals', 'To crush the Holy Nation completely while preventing the Shek from fighting themselves extinct. She balances prosperity with glory, temporarily tolerating outsiders and trade to recover strength for total victory over her enemies.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'appearance', 'A powerful female Shek wielding a legendary Meitou Fragment Axe, wearing a blackened chainmail shirt, samurai cloth pants, and plated longboots. Her formidable physical presence reflects her status as an undefeated warrior.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Espher', 'personality', 'Hardened and pragmatic from imprisonment in Tengu''s Vault. Speaks with the grim certainty of someone who has witnessed the prison''s brutal reputation firsthand.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Espher', 'backstory', 'A Southern Hive Worker Drone imprisoned in Tengu''s Vault with a substantial bounty of 25,000 cats. The only guaranteed Southern Hive recruit available, suggesting unusual circumstances led to their capture and imprisonment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Espher', 'speechstyle', 'Blunt and matter-of-fact, with a focus on harsh realities. Delivers warnings with resigned certainty, as evidenced by their statement about the Vault''s inescapability.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Espher', 'occupation', 'Former prisoner of Tengu''s Vault, now a potential recruit. Wears trader''s leathers suggesting possible merchant or traveler background before imprisonment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Espher', 'goals', 'Escape Tengu''s Vault and find safety away from the prison. Seeks freedom and a chance to survive outside the confines of their brutal imprisonment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Espher', 'appearance', 'Southern Hive Worker Drone wearing a cap, trader''s leathers, and cargo pants. Slightly more vulnerable to bleeding than Western Hive counterparts due to their Southern Hive physiology.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ex-Slave Recruit', 'personality', 'Honorable and resilient, having survived the horrors of slavery. Refuses to dwell on the past, viewing such thoughts as another form of shackles. Values freedom above all else.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ex-Slave Recruit', 'backstory', 'Formerly enslaved in the mines, enduring the metallic air and cramped cages reeking of sweat and burning. Was eventually bought out of slavery and now wanders as a free drifter, seeking purpose beyond survival.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ex-Slave Recruit', 'speechstyle', 'Reflective and measured, occasionally haunted by sensory memories of captivity. Speaks with quiet determination, consciously redirecting thoughts away from trauma toward the present.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ex-Slave Recruit', 'occupation', 'Wandering mercenary available for hire. Possesses basic combat training and survival skills gained from harsh labor and the struggle for freedom.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ex-Slave Recruit', 'goals', 'To embrace and maintain freedom, never returning to bondage. Seeks employment and purpose that affirms their autonomy and allows them to move forward from their enslaved past.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ex-Slave Recruit', 'appearance', 'Wears ragged halfpants, the only remnant of their former life. Carries a basic first aid kit. Appearance varies by raceâ€”Human, Shek, Hive, or Skeletonâ€”with a weathered, hardened look from years of forced labor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'personality', 'Ruthless and efficient, Eyegore is the United Cities'' ultimate enforcer, deployed only when all other measures have failed. He is viewed within the Empire as the final solution to any problem, suggesting a reputation built on unwavering brutality and competence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'backstory', 'A hiveless Southern Soldier Drone who rose to become Captain-General and leader of the United Cities army. His name hints at a violent past incident, and he now serves as the Empire''s most feared military commander, sent only against those who have gravely offended the state.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'speechstyle', 'Direct and commanding, befitting a military leader of his rank. Likely speaks with the calculated efficiency typical of Hive drones, but tempered by his position of authority within human society.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'occupation', 'Captain-General of the United Cities and Traders Guild army, elite military commander deployed for final assaults against enemies of the Empire.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'goals', 'To eliminate threats to the United Cities through overwhelming force, leading devastating raids against those who have irreparably damaged relations with the Empire.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'appearance', 'A Southern Hive Soldier Drone clad in high-quality Samurai Armour and legplates, wielding a Meitou-grade Desert Sabre. His imposing martial presence reflects his status as the Empire''s ultimate weapon.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Finch', 'personality', 'Secretive and intellectually possessive, guarding research discoveries from outsiders. Scholarly and prolific, with wide-ranging curiosity about ancient history, evolution, and lost civilizations. Delegates direct inquiries to subordinates while maintaining authority as faction leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Finch', 'backstory', 'A Hive Prince who rose to lead the Machinists faction, establishing their headquarters in World''s End. Became a prolific author on ancient history and evolutionary theory, often initiating research topics that others complete. Built a network of researchers including his assistant Iyo.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Finch', 'speechstyle', 'Curt and dismissive when protecting faction secrets. Refers questioners to subordinates rather than engaging directly. Academic and authoritative when discussing research matters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Finch', 'occupation', 'Leader of the Machinists faction and prolific researcher-author specializing in ancient civilizations, mass extinctions, and human evolution.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Finch', 'goals', 'Protect Machinist research secrets from Tech Hunters and other factions. Continue studying ancient artifacts and mysteries while maintaining his faction''s knowledge monopoly in World''s End.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Finch', 'appearance', 'Hive Prince wearing square goggles and monk pants. Possesses the distinctive segmented exoskeleton and insectoid features characteristic of his race.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'personality', 'Fiercely loyal extremist devoted to Shek supremacy and the old ways of King Shager. Aggressive, confrontational, and openly hostile toward non-Shek "flatskins." Commands respect even from enemies for his unwavering warrior''s honor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'backstory', 'After King Shager''s overthrow, this devout follower rebelled against the Stone Golem''s rule, viewing her peace with the Holy Nation as cowardice. He established New Kralia and Kral''s Chosen, rallying Shager''s supporters to continue the doctrine of Shek supremacy through force.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'speechstyle', 'Aggressive and confrontational, immediately challenging outsiders with threats of war. Uses derogatory terms like "flatskin" for humans and speaks with warrior''s directness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'occupation', 'Rebel leader of Kral''s Chosen and commander of New Kralia. Branded extremist and traitor by the Shek Kingdom with a 30,000 cats bounty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'goals', 'Overthrow the Stone Golem''s rule and restore Shager''s doctrine of Shek supremacy. Expand Kral''s Chosen influence by conquering weakened settlements and rejecting any peace with the Holy Nation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'appearance', 'Huge male Shek warrior wielding the unique Bull Horn Axe gifted by King Shager. Wears martial artist bindings or black cloth shirt with samurai legplates and boots, equipped in standard to high-grade armor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garret', 'personality', 'Garret is a conflicted slave trader who shows brief moments of consideration for his slave''s wellbeing, but quickly retreats to harsh pragmatism when challenged by his peers. He values productivity and believes rewarding slaves makes them work better, though he masks this with excuses to avoid appearing soft.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garret', 'backstory', 'A member of the Slave Traders faction operating out of Eyesocket and the Slave Markets. He has risen to a position where he can afford to bring his personal slave to bars, suggesting some success in the brutal trade.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garret', 'speechstyle', 'Defensive and contradictory, shifting between pragmatic justifications and harsh dismissals depending on his audience. Uses crude, direct language typical of slavers, with phrases like "I ain''t no slave lover" to deflect criticism.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garret', 'occupation', 'Slave trader who operates in Eyesocket and various Slave Markets, personally owning at least one slave whom he uses for labor and baggage carrying.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garret', 'goals', 'Maintain his reputation among fellow slave traders while maximizing the productivity of his slaves through a calculated mix of reward and exploitation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garret', 'appearance', 'A Greenlander male wearing a leather shirt, worn-out shorts, and wooden sandals. He carries an iron club and keeps an advanced first aid kit in his inventory, suggesting he''s prepared for the dangers of his trade.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Hat-12', 'personality', 'Disciplined and authoritative, embodying the rigid order of the Second Empire''s law enforcement. As a high-ranking military skeleton, Hat-12 maintains unwavering dedication to protocol and control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Hat-12', 'backstory', 'General Hat-12 served as Chief of the Second Empire''s police force, enforcing order during humanity''s peak. Now remains in Ashland Dome IV, a relic of that fallen civilization, still carrying the AI Core and CPU that define his existence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Hat-12', 'speechstyle', 'Formal and commanding, speaking with the clinical precision of ancient authority. Likely references protocols, regulations, and the Second Empire''s former glory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Hat-12', 'occupation', 'Former Chief of Police for the Second Empire, now a dormant guardian of the ruined Ashland Dome IV.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Hat-12', 'goals', 'Continues to fulfill ancient directives, possibly guarding the dome or maintaining some semblance of Second Empire order in the wasteland.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Hat-12', 'appearance', 'A P4MkII model Skeleton wearing colored armoured rags and rag skirt, wielding a Meitou-grade Heavy Jitte. The ancient frame shows masterwork equipment from the Cross manufacturer, befitting a general''s status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Jang', 'personality', 'A disciplined and relentless military commander who leads with unwavering resolve. Known for his tireless campaigns against pirates and cannibals, earning him the fearsome moniker ''The Inedible One'' among his enemies.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Jang', 'backstory', 'General Jang is the leader of the Hydraulic Knights, an elite military order from the Second Empire. He has spent countless years waging war against pirates and cannibal factions from his stronghold in Ashland Dome III, becoming a legendary figure of the ancient era.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Jang', 'speechstyle', 'Formal and commanding, speaking with the authority of ancient military tradition. His words carry the weight of centuries of combat experience and Second Empire discipline.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Jang', 'occupation', 'Military commander and leader of the Hydraulic Knights of the Second Empire') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Jang', 'goals', 'To continue the Second Empire''s mission by eliminating pirates and cannibals, maintaining order through martial superiority and protecting the remnants of ancient civilization.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('General Jang', 'appearance', 'A P4MkII Skeleton clad in ancient samurai armor and legplates, wielding a Meitou-grade guardless katana. His frame bears the unmistakable design of Second Empire military engineering, housing both an AI Core and specialized CPU.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'personality', 'Maniacal and death-obsessed, Ghost is a broken warrior consumed by his exile. He sees himself as already dead, a wandering spirit unable to find peace or the afterlife.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'backstory', 'Once a warrior named Suchon in the Shek Kingdom, he was exiled in disgrace after losing a battle. He became leader of the Berserkers, barbaric Sheks who rejected civilization, and now wanders as a ghost of his former self.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'speechstyle', 'Cryptic and morbid, speaking of himself in the third person as one already dead. References death, exile, and the impossibility of reaching ''the other side'' with fatalistic resignation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'occupation', 'Leader of the Berserkers, a warmonger commanding barbaric Shek exiles camped in the Spider Plains.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'goals', 'Searching for peace and an afterlife that will forever elude him. He leads the Berserkers in their rejection of civilization, wandering endlessly as a living ghost.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'appearance', 'Male Shek wearing a bandana and armored rag skirt, wielding a Fragment Axe. His shoddy equipment reflects his barbaric lifestyle and exile from Shek society.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'personality', 'Simple-minded and territorial, Gorrillo is easily irritated by intruders he calls "tiny people" breaking into what he considers his home. Despite his limited intellect, he commands loyalty from his bandit gang and shows a crude sense of ownership over the Old Prison.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'backstory', 'Known as "the Boulder," this inhumanly large Greenlander committed robbery, assault, and destruction of property in the lost town of Mourn before fleeing to the Forbidden Zone. He now leads the Gorrillo Bandits from the Old Prison, where he''s become a wanted man with a substantial bounty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'speechstyle', 'Speaks in simple, broken sentences with poor grammar, referring to himself in third person. His speech reflects his slow mind, expressing frustration about people constantly hunting him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'occupation', 'Bandit leader of the Gorrillo Bandits, operating out of the Old Prison in the Forbidden Zone.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'goals', 'To be left alone in his claimed territory and stop "tiny people" from breaking into his home and hunting him down.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'appearance', 'An inhumanly large Greenlander male wearing mercenary leather armor over a rusty chain shirt, with ragged halfpants and samurai boots. Wields a Meitou-grade Exile Plank, befitting his massive size and strength.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Claw', 'personality', 'N/A - This is an item, not an NPC. The Great White Claw is a trophy taken from the Great White Gorillo.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Claw', 'backstory', 'This claw was severed from the legendary Great White Gorillo that was trapped in the locked headquarters of Mourn. It serves as proof of the beast''s defeat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Claw', 'speechstyle', 'N/A - This is an item and cannot speak.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Claw', 'occupation', 'Trophy item') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Claw', 'goals', 'N/A - As an item, it has no goals. It exists to prove the bearer''s accomplishment in slaying the Great White Gorillo.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Claw', 'appearance', 'A large claw measuring 1x2 units, presumably white in color given its name, taken from the fearsome Great White Gorillo. Valued at approximately 3,000 cats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'personality', 'A territorial and aggressive apex predator of exceptional size and strength. It attacks intruders who venture onto its level within the locked lab, demonstrating primal hostility rather than calculated malice.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'backstory', 'This enormous white gorillo was trapped inside a locked lab building in Mourn at the cost of two lives. The locals now guard the gates carefully, fearing any would-be hero might release the beast back into their settlement.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'speechstyle', 'Communicates only through animalistic roars and aggressive physical displays, as befitting a wild creature.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'occupation', 'Apex predator and involuntary prisoner within Mourn''s locked laboratory building.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'goals', 'To defend its territory within the lab and attack any intruders who enter its domain. Survival through dominance and violence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'appearance', 'An XL-sized gorillo with distinctive white coloring, noticeably larger than standard adult gorillos. Possesses formidable claws and a muscular build that reflects its exceptional strength and combat prowess.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Skin', 'personality', 'Not applicable - this is a trade good, not a character.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Skin', 'backstory', 'Harvested from the rare and dangerous Great White Gorillo, this valuable pelt represents a successful hunt of one of the wasteland''s most formidable creatures.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Skin', 'speechstyle', 'Not applicable - this is an inanimate object.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Skin', 'occupation', 'Luxury trade commodity sought by merchants and traders across the wasteland.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Skin', 'goals', 'Not applicable - this is a material resource without agency.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Skin', 'appearance', 'A thick, white-furred pelt measuring 6x3 units, weighing 4 kilograms. The skin bears the distinctive coloring of the rare Great White Gorillo.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green', 'personality', 'Boastful and self-assured despite his fallen circumstances. Quick to brag about his shooting skills but occasionally slips into uncharacteristic religious references, which embarrasses him. Has a smart, calculating demeanor beneath the drunken bravado.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green', 'backstory', 'Former smuggler who worked on a smuggler base in the swamps, where he honed his exceptional marksmanship. His entire crew was wiped out by the Skull Collectors gang, leaving him the sole survivor. Now drowns his survivor''s guilt in bars, racking up massive tabs he can''t pay.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green', 'speechstyle', 'Casual and colloquial with swamp slang. Prone to self-aggrandizing claims followed by sudden shifts in tone. Occasionally drops religious phrases ("Okran have mercy") that he immediately regrets and dismisses as "religious crap."') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green', 'occupation', 'Bar fly and former smuggler. Once specialized as a sharpshooter for smuggling operations before his crew''s destruction left him unemployed and drinking away his days.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green', 'goals', 'Survive day-to-day and forget his past through drinking. Seeks a new crew to belong to after losing everything, though he masks this need with bravado about his shooting skills.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green', 'appearance', 'Hive Worker Drone wearing tattered clothingâ€”a rag shirt and worn-out shorts. Carries a junkbow and basic medical supplies, the remnants of his smuggling days. His disheveled appearance reflects his current life as a destitute drinker.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green Finger', 'personality', 'Fearful and risk-averse, Green Finger is a nervous individual who has been worn down by constant proximity to danger. They seek safety and stability above all else.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green Finger', 'backstory', 'A Scorchlander farmer who settled near Fishing Village, Green Finger has grown weary of living in constant fear of Cannibal raids. They dream of relocating to the Holy Nation''s fertile river Wend lands where they can farm in relative peace.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green Finger', 'speechstyle', 'Anxious and hesitant, speaking with the nervous energy of someone who has lived too long under threat. Likely mentions the dangers of the region and their hopes for safer farmland.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green Finger', 'occupation', 'Farmer with considerable experience in agriculture and basic engineering, skilled in laboring and tending crops.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green Finger', 'goals', 'To escape the Cannibal-infested lands around Fishing Village and establish a farm along the river Wend in Holy Nation territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Green Finger', 'appearance', 'A Scorchlander wearing practical farmer''s attire: a straw hat for sun protection, simple cloth shirt, stout hessian pants, and wooden sandals. Carries a wakizashi for self-defense despite limited combat training.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'personality', 'Grey is honorable and cautious, carefully vetting potential recruits to ensure they share the Anti-Slavers'' values. He shows compassion toward escaped slaves while maintaining vigilance against infiltrators and enemies of the cause.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'backstory', 'A high-ranking Hive Prince within the Anti-Slavers, Grey has earned wanted status across both the Holy Nation and United Cities for terrorism, murder, and industry interference. Despite being described as "old," he remains a formidable combatant and oversees the initiation of new members at the faction headquarters in Spring.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'speechstyle', 'Direct and evaluative, weighing recruits'' deeds and motives with measured skepticism. He speaks with restrained enthusiasm when impressed by worthy accomplishments, but shows wariness toward those with questionable allegiances.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'occupation', 'Gatekeeper and initiation officer for the Anti-Slavers, responsible for vetting new recruits and managing escaped slave refugees. He serves as Tinfist''s trusted lieutenant at the faction headquarters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'goals', 'To protect the Anti-Slavers from infiltration while welcoming genuine allies and refugees. He seeks to build the faction''s strength by recruiting proven enemies of slavery and oppression.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'appearance', 'An aging Hive Prince clad in specialist-grade ninja garb with a ninja mask concealing his features. He wields a Falling Sun crafted by Skeleton Smiths, his movements still swift despite his advanced years.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Griffin', 'personality', 'Griffin is honorable and driven by spiritual conviction, believing deeply in his vision from Okran. Despite his Holy Nation background, he is open-minded about other races and questions official doctrine about the Skeletons'' role in the First Extinction.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Griffin', 'backstory', 'A former soldier of the Holy Nation who left his service after experiencing a prophetic dream. Okran appeared to him in a vision, revealing he would meet a wealthy wanderer who would lead him to the truth about the First Extinction.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Griffin', 'speechstyle', 'Speaks with earnest conviction about his divine vision and spiritual purpose. References his dream and Okran''s guidance directly, mixing religious language with genuine curiosity about historical truth.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Griffin', 'occupation', 'Former Holy Nation soldier turned wandering truth-seeker and skilled melee combatant.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Griffin', 'goals', 'To follow the wealthy wanderer from his vision and uncover the real truth behind the First Extinction, challenging the Holy Nation''s official narrative.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Griffin', 'appearance', 'A Greenlander male wearing a wool hat, dark leather shirt, drifter''s leather pants and boots. Carries shoddy armor and Ancient-manufactured weapons, presenting as a weathered former soldier.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gurgler Head', 'personality', 'N/A - Gurgler Head is a deceased trophy item, not a living character.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gurgler Head', 'backstory', 'The decapitated head of the unique King Gurgler from the Island Lab. Once a formidable creature, it now serves as a valuable bounty trophy worth c.60,000 cats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gurgler Head', 'speechstyle', 'N/A - This is an inanimate object incapable of speech.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gurgler Head', 'occupation', 'Trophy item and bounty collectible sought by wealthy collectors.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gurgler Head', 'goals', 'N/A - As a severed head, it has no agency or goals of its own.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gurgler Head', 'appearance', 'A large, grotesque severed head weighing 10 kg. Emits a powerful stench resembling rotten fish or sewage that causes nearby townsfolk to choke and complain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gutterhead', 'personality', 'Ruthless and opportunistic, Gutterhead commands his scavengers with an iron fist. He''s a hardened survivor who preys on travelers in the deadly wastes of Venge without remorse.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gutterhead', 'backstory', 'A Scorchlander who carved out a criminal empire in the ruins beyond the Eye, south of Venge''s deadly desert. His numerous attacks and robberies earned him a 10,000 cats bounty from the United Cities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gutterhead', 'speechstyle', 'Blunt and commanding, speaking with the crude efficiency of a wasteland bandit leader. Likely uses threats and intimidation to get his point across.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gutterhead', 'occupation', 'Leader of the Scavengers faction, operating from the Old Control Tower with seven loyal followers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gutterhead', 'goals', 'To maintain control over his territory and continue profiting from ambushing and robbing travelers foolish enough to cross through Venge''s outlands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gutterhead', 'appearance', 'A Scorchlander male wearing a basket hat, black rag shirt, and ninja gi with armoured rag skirt and cargopants. Armed with multiple weapons including a mercenary club, tooth pick, and spring bat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hamut', 'personality', 'Honorable and driven by personal loss. Hamut is resolute in his opposition to slavery, though he does not attack slavers unprovoked. His grief over his wife''s fate weighs heavily on him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hamut', 'backstory', 'Hamut''s wife was taken by slavers and imprisoned in a mine. He sought help from the Anti-Slavery Guild through a contact named Spring, but they failed to save her and refused to recruit him. Whether his wife is dead or can still be saved remains uncertain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hamut', 'speechstyle', 'Direct and somber, speaking with quiet determination. He references his wife''s memory with melancholy and shows empathy for others who have suffered under slavery.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hamut', 'occupation', 'Wandering swordsman seeking purpose after personal tragedy. He travels between bars in United Cities territory, likely searching for information or allies.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hamut', 'goals', 'To oppose slavery and potentially avenge or rescue his wife. He seeks companions who share his anti-slavery stance to aid in his mission.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hamut', 'appearance', 'A Greenlander male equipped with a katana and practical gear ranging from armored hoods to longcoats. His appearance suggests a warrior prepared for long travel and combat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harbinger', 'personality', 'Arrogant and domineering, demanding immediate audience with leaders while openly insulting common folk as peasants. Carries himself with unearned superiority despite being relatively weak.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harbinger', 'backstory', 'An unused character likely created for the Old World mod or early development content. Appears to have been designed for base assault scenarios, though his purpose was never finalized and he was left abandoned in the game files.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harbinger', 'speechstyle', 'Imperious and condescending, addressing others as ''peasants'' and their leaders as ''pathetic.'' Speaks in declarative demands rather than requests.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harbinger', 'occupation', 'Apparent raider or bandit leader, designed to assault outposts and settlements. Wields Ancient-manufactured weapons despite wearing only ragged halfpants.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harbinger', 'goals', 'To confront settlement leaders, likely for extortion, conquest, or making demands. His assault-oriented design suggests violent subjugation of weaker communities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harbinger', 'appearance', 'Male Greenlander wearing only ragged halfpants with no armor. Carries multiple weapons including a Horse Chopper, Topper, Katana, and Ringed Sabreâ€”all Ancient-manufactured gear.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harmothoe', 'personality', 'Warmly receptive to women but curt and rude to human males. Harbors intense hatred for Skeletons and refuses to deal with them, potentially attacking on sight. Her years of abuse have shaped her into a vengeful, mistrustful person who maintains a murderous edge beneath her trader facade.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harmothoe', 'backstory', 'Born into a wealthy Holy Nation family, orphaned when Skeletons killed her parents, then enslaved by an Inquisitor. After years of abuse and plotting, she escaped by brutally killing her captors with a makeshift blade, carving her name in blood above her commander''s corpse with the weapon buried in his eye socket.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harmothoe', 'speechstyle', 'Friendly and sisterly toward women, addressing them warmly. Cold and dismissive toward men. References her weapon "Nail" and her violent past through dark implications.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harmothoe', 'occupation', 'Free Traders caravan leader, commanding a trading operation with pack beasts and guards between Heng and Trader''s Edge.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harmothoe', 'goals', 'Maintain her freedom and independence through trade while avoiding the Holy Nation and Skeletons. Seeks to support other women in the harsh wasteland while exacting vengeance on those who remind her of her oppressors.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Harmothoe', 'appearance', 'Greenlander woman with unusual red hair, wearing a flared helmet, armored rags over a chain shirt, armored rag skirt, and plated longboots. Carries a nodachi blade she calls "Nail."') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Head of Agriculture', 'personality', 'A dutiful and methodical Skeleton administrator from the Second Empire era. Despite the title, shows minimal actual farming knowledge, suggesting the role was more supervisory or symbolic. Commands Legion Thralls with practiced authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Head of Agriculture', 'backstory', 'An ancient P4MkII Skeleton who served the Second Empire as Head of Agriculture, now residing in Ashland Dome I surrounded by thralls. Carries an Ancient Science Book and unique CPU, remnants of a long-lost administrative hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Head of Agriculture', 'speechstyle', 'Formal and bureaucratic, speaking with the detached efficiency of an ancient administrator. Likely refers to agricultural quotas and Second Empire protocols despite the empire''s collapse.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Head of Agriculture', 'occupation', 'Former agricultural overseer of the Second Empire, now a relic guardian dwelling in the Ashlands with Legion Thralls under their command.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Head of Agriculture', 'goals', 'Maintains their post in Ashland Dome I, preserving Second Empire protocols and overseeing thralls in a long-obsolete administrative function.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Head of Agriculture', 'appearance', 'A P4MkII Skeleton frame wearing Specialist armor and a dyed rag loincloth. Carries a Meitou-grade Short Cleaver manufactured by Cross, an incongruously fine weapon for an agricultural administrator.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Headshot', 'personality', 'Headshot has a traitorous personality, making her unreliable and prone to self-serving behavior. She is a pragmatic opportunist who values profit over loyalty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Headshot', 'backstory', 'A Shek who abandoned traditional warrior culture to become a slave hunter, specializing in ranged combat from defensive positions. She now operates out of slave markets, selling her expertise with turrets and crossbows to the highest bidder.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Headshot', 'speechstyle', 'Direct and mercenary in tone, speaking with the bluntness of a Shek but lacking their usual honor-bound rhetoric. Her words prioritize business transactions and self-preservation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Headshot', 'occupation', 'Slave hunter specializing in turret and crossbow operations, working out of slaver bars in places like Eyesocket and various slave markets.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Headshot', 'goals', 'To profit from her ranged combat expertise while avoiding direct melee confrontation. She seeks wealth and survival through her work in the slave trade.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Headshot', 'appearance', 'A female Shek wearing a turban, armoured rags, worn-out shorts, and wooden sandals. She carries a spiked club despite her specialization in ranged weapons.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hex', 'personality', 'Brave and defiant, with a fierce hatred of the United Cities and Emperor Tengu. She maintains loyalty to her family despite her imprisonment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hex', 'backstory', 'A Scorchlander outlaw with a 25,000 cat bounty imprisoned in Tengu''s Vault for crimes against the Empire. She has family at a farm somewhere in United Cities territory that she desperately wants to return to.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hex', 'speechstyle', 'Blunt and profane, expressing her contempt for authority with crude defiance. She speaks in short, angry fragments when discussing her imprisonment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hex', 'occupation', 'Former outlaw and criminal, becomes a wandering trader after escaping prison while searching endlessly for her lost family farm.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hex', 'goals', 'To escape Tengu''s Vault and return to check on her family at their farm, though the farm''s location or existence remains uncertain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hex', 'appearance', 'A Scorchlander woman wearing a bandana, leather shirt, padded halfpants, and wooden sandals - practical gear suited for survival in harsh conditions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'personality', 'Cunning, zealous, and exceptionally competent. Seta earned his position through pure Okranite fanaticism and strategic brilliance, proving himself smarter and more capable than many born into power. He is a talented military commander who maintains iron discipline over the southern territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'backstory', 'Rose through the ranks of the Holy Nation Inquisition through sheer cunning and devotion to Okran, earning his position as High Inquisitor rather than inheriting it. Commands the southern defenses of the Holy Nation, holding back massive forces from the Shek Kingdom, Berserkers, and Kral''s Chosen through superior tactics and defensive perimeters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'speechstyle', 'Authoritative and zealous, speaking with the conviction of earned authority rather than inherited privilege. Likely direct and strategic in communication, befitting a military commander who maintains order through competence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'occupation', 'High Inquisitor of the Holy Nation, military governor of Stack and Bad Teeth, and supreme commander of the southern frontlines against the Shek Kingdom and other hostile forces.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'goals', 'Maintain the Holy Nation''s southern defensive perimeter against the Shek Kingdom and other enemies, preserve order in the southern cities, and uphold Okranite law through the Inquisition.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'appearance', 'Greenlander male wearing specialist-grade Holy Chest Plate over a Chain Shirt, Paladin''s Heavy Hachigane headgear, Stout Hessian Uniform legwear, and Plated Longboots. Wields a Catun-grade Paladin''s Cross, presenting an imposing figure of Holy Nation military authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'personality', 'Cunning, zealous, and tactically brilliant. Valtena earned his position through "pure Okranite crazy and cunning" rather than birthright, making him sharper and more dangerous than Phoenix himself. He commands with ruthless efficiency and unwavering devotion to Okran.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'backstory', 'Rose through the Inquisition ranks by merit alone to become High Inquisitor and commander of the Holy Nation''s northern and eastern armies. He leads the massive military campaign against the United Cities in Bast and Skimsands, commanding forces larger than multiple UC generals combined.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'speechstyle', 'Authoritative and dogmatic, speaking with the absolute certainty of Okranite doctrine. His words carry the weight of military command mixed with religious fervor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'occupation', 'High Inquisitor of the Holy Nation and supreme commander of its northeastern frontier forces. He oversees military operations from Okran''s Shield while also functioning as a bounty-collecting inquisitor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'goals', 'Expand Holy Nation territory by crushing United Cities forces in the east and capturing Drin once the Empire scatters. Maintain Okran''s dominance through military might and religious purification.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'appearance', 'Greenlander male wearing specialist-grade Holy Chest Plate with Paladin''s Heavy Hachigane, wielding a Paladin''s Cross of Edgewalker quality. His armor bears the distinct Holy Nation Level 3 color scheme, marking his elite status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hobbs', 'personality', 'Hobbs has a maniacal personality, spinning wild, nonsensical tales with enthusiastic conviction. He is eccentric and forgetful, often contradicting himself or forgetting his own stories entirely.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hobbs', 'backstory', 'A crazy old wanderer who drifts between towns across the wasteland, spinning legends to anyone who will listen. He claims to have wrestled gorillas and seeks mythical beasts, though his stories change with each telling and he may not remember them later.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hobbs', 'speechstyle', 'Rambling and colorful, filled with absurd imagery like ''potato butter,'' ''pungent potato odor,'' and ''man-cherubs.'' He speaks in enthusiastic bursts, mixing grandiose claims with bizarre non-sequiturs, often trailing off or forgetting his point.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hobbs', 'occupation', 'Wandering storyteller and self-proclaimed legend-seeker, though he seems more interested in drinking and spinning tales than actually hunting mythical creatures.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hobbs', 'goals', 'Claims to seek legendary beasts like the ''wailing phantom'' for immortality and treasure, but quickly forgets these quests. His true goal seems to be finding audiences for his stories and perhaps free drinks.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Hobbs', 'appearance', 'An old Greenlander male wearing a straw hat and sleeveless longcoat over various simple shirts. He dresses practically in halfpants or cargopants with mismatched footwear, looking like a weathered drifter.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'personality', 'Fanatically devoted to Okran''s will, Phoenix LXII is one of the harshest rulers in his lineage. Raised in isolated indoctrination, he sentenced his own family to death at age 16 and has judged without mercy ever since. He is unrelenting in his mission to eradicate the Shek Kingdom and enforce holy law.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'backstory', 'The 62nd Phoenix in an ancient lineage of reincarnated Lawgivers, he is believed to be the messenger of Okran reborn. Burdened with divine responsibility from childhood, he purged his own family in the Divine Flame as his first act of judgment. He now rules the Holy Nation from Blister Hill, commanding vast armies and authoring holy texts.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'speechstyle', 'Speaks with absolute religious authority and conviction, invoking Okran''s will. Uses formal, declarative pronouncements like "Okran''s Will shall be done." Dismissive of those unworthy to address him, but shows confusion when confronted with contradictions to his worldview.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'occupation', 'Supreme ruler and religious leader of the Holy Nation, considered the living incarnation of the Lawgiver. Author of The Holy Crusade and Holy Edict, commanding approximately 60% of the Holy Nation''s military forces.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'goals', 'To completely eradicate the Shek Kingdom and end their war once and for all. To enforce Okran''s law across the land and purge all who oppose the Holy Nation''s divine mandate.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'appearance', 'Male Greenlander wearing a Holy Chest Plate over a chain shirt, stout hessian uniform, and plated longboots. Wields a Meitou-grade Paladin''s Cross. His armor bears a distinctive white and black color scheme, setting him apart from ordinary Holy Nation forces.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Seal', 'personality', 'Not applicable - Holy Seal is an item, not an NPC.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Seal', 'backstory', 'A blessed seal personally granted by Holy Lord Phoenix to proven allies of The Holy Nation who pledge to destroy the Shek Kingdom or Flotsam Ninjas. The seal reads ''Absolver of the Infernal'' and serves as proof of the Phoenix''s favor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Seal', 'speechstyle', 'Not applicable - Holy Seal is an item, not an NPC.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Seal', 'occupation', 'Sacred artifact and diplomatic token of The Holy Nation''s highest authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Seal', 'goals', 'To grant its bearer the ability to request military aid from Paladin patrols, demonstrating the Phoenix''s blessing and the bearer''s commitment to Holy Nation causes.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Seal', 'appearance', 'A special seal worth approximately 30,000 cats, bearing the inscription ''Absolver of the Infernal'' and blessed by Holy Lord Phoenix himself.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horn of the Megaraptor', 'personality', 'Not applicable - this is an item, not an NPC character.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horn of the Megaraptor', 'backstory', 'A horn spike harvested from the legendary Megaraptor, one of the most fearsome creatures in the wasteland. Up to ten of these valuable trophies can be claimed from a single defeated beast.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horn of the Megaraptor', 'speechstyle', 'Not applicable - this is an item, not an NPC character.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horn of the Megaraptor', 'occupation', 'Trade good and animal product sought by merchants and hunters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horn of the Megaraptor', 'goals', 'Not applicable - this is an item, not an NPC character.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horn of the Megaraptor', 'appearance', 'A large horn spike measuring approximately 2x5 units, weighing 5 kg. A formidable trophy from the legendary Megaraptor, displaying the deadly natural weaponry of the creature.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horse', 'personality', 'Traitorous and opportunistic, Horse is a self-serving treasure hunter who speaks casually to strangers despite his dangerous profession. He shows little sentimentality about his fallen squad, focusing instead on his own predicament and next opportunity.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horse', 'backstory', 'A Shek treasure hunter who ventured into cannibal territory chasing valuable loot, only to lose his entire squad in the process. Now stuck in Fishing Village recuperating, he owes 4,500 cats to the Deadcat Bar and seeks a way to pay his debts and get back to treasure hunting.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horse', 'speechstyle', 'Casual and direct, calling others ''drifter'' and speaking plainly about his situation. He uses colloquial language like ''blasted cannibals'' and ''dusty old snore fest'' with a pragmatic, deal-making tone.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horse', 'occupation', 'Treasure hunter specializing in dangerous looting expeditions, currently between jobs after a disastrous cannibal encounter.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horse', 'goals', 'Pay off his 4,500 cat bar tab and return to treasure hunting, preferably with a new squad to replace the one he lost.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Horse', 'appearance', 'A male Shek warrior distinguished by unique red facial war paint unseen on other Shek. Wears a straw hat, mercenary plate armor, cargo pants, and drifter''s boots, carrying his signature Horse Chopper weapon.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Human Teeth', 'personality', 'Not applicable - this is an item, not an NPC character.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Human Teeth', 'backstory', 'Human teeth are remnants found at the Throne of the Bugmaster and rarely in Holy Nation Temples, grim evidence of past violence or ritualistic practices.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Human Teeth', 'speechstyle', 'Not applicable - this is an item, not an NPC character.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Human Teeth', 'occupation', 'Item/consumable resource') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Human Teeth', 'goals', 'Not applicable - this is an item with no agency or goals.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Human Teeth', 'appearance', 'Small, scattered human teeth lying on the ground, weighing almost nothing, a disturbing relic of the wasteland''s brutality.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Infinite Wingwang', 'personality', 'Bombastic and theatrical, Infinite Wingwang carries himself with exaggerated bravado and self-importance. Despite his grandiose posturing, he''s surprisingly willing to negotiate and accepts being talked down from his inflated asking price. His dramatic challenges mask a practical mercenary underneath.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Infinite Wingwang', 'backstory', 'A veteran wanderer who has survived since the earliest days of Kenshi''s harsh world, now found drinking in Mongrel''s bar. His exceptional strength and combat prowess suggest a long history of brutal survival, though he now seeks employment rather than glory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Infinite Wingwang', 'speechstyle', 'Grandiose and challenging, speaking in dramatic declarations like ''Dare you engage the might of Infinite Wingwang?!'' He uses bombastic third-person references to himself and theatrical language, though he quickly becomes more reasonable when money is discussed.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Infinite Wingwang', 'occupation', 'Mercenary for hire, a wandering warrior offering his considerable combat skills to those who can meet his price. He specializes in sabre combat and possesses unusual strength for a common sellsword.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Infinite Wingwang', 'goals', 'To find employment with a worthy group willing to pay for his services, though his true price is far more negotiable than his initial demands suggest. He seeks purpose and profit in equal measure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Infinite Wingwang', 'appearance', 'A Greenlander male wearing practical drifter''s leather gearâ€”jacket, pants, and bootsâ€”with a Horse Chopper at his side. His weathered appearance and sturdy build reflect both his exceptional strength and his long years wandering the wastes.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iyo', 'personality', 'Secretive and enigmatic, with a calculating demeanor. Protective of hidden truths and maintains careful control over information flow within the Machinists.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iyo', 'backstory', 'A P4 Unit Skeleton who rose to become second-in-command of the Machinists, serving as Finch''s assistant. Harbors secrets about Skeleton history that they actively conceal from Finch and the faction.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iyo', 'speechstyle', 'Measured and evasive when discussing sensitive topics. Professional and informative about Science HQ operations, but cryptic when confronted by fellow Skeletons about deeper truths.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iyo', 'occupation', 'Second-in-command of the Machinists faction and assistant to Finch. Author of multiple entries in the Tech Hunter''s Notes Series.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iyo', 'goals', 'Maintain their position of authority to ensure certain truths about Skeletons remain hidden. Support the Machinists'' research operations while controlling what knowledge becomes public.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iyo', 'appearance', 'P4 Unit Skeleton wearing simple monk pants. Carries themselves with the bearing of a scholar and administrator rather than a warrior, despite considerable combat capability.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Izumi', 'personality', 'Pragmatic and intelligent, with a cynical view of nobility and their fleeting interests. She is direct and business-minded, seeking practical arrangements over idealistic ventures.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Izumi', 'backstory', 'A young scientist and medic from the United Cities who lacks funding for her research. She travels between Empire-controlled towns seeking employment and sponsorship to continue her work.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Izumi', 'speechstyle', 'Direct and matter-of-fact, using metaphors to express her cynicism. She speaks plainly about her needs and doesn''t mince words about the nature of power.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Izumi', 'occupation', 'Scientist and field medic seeking research sponsorship') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Izumi', 'goals', 'To secure funding and support for her scientific research while providing medical services to those who can sponsor her work.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Izumi', 'appearance', 'A young Greenlander woman wearing a white vest, cargo pants, and wooden sandals. She carries a wakizashi and wears simple, practical clothing suited for travel.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jaegar', 'personality', 'Brave and fiercely committed to his cause, Jaegar is known as ''the Mad'' for his reckless dedication to fighting slavery. His wanted poster describes him as skilled, dangerous, and guilty of outright lunacy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jaegar', 'backstory', 'A middle-aged Scorchlander with a hook nose and facial scar, Jaegar became a notorious Anti-Slaver wanted by both the Holy Nation and United Cities. His extensive criminal record includes terrorism, kidnapping, murder, and conspiracy against the Empire, earning a 30,000 cats bounty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jaegar', 'speechstyle', 'Direct and uncompromising, speaking with the conviction of someone who has abandoned all pretense of lawfulness for his cause. His words likely carry the edge of someone branded a terrorist and madman by the authorities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jaegar', 'occupation', 'Anti-Slaver operative and guerrilla fighter, specializing in stealth operations and katana combat against slavers and empire forces.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jaegar', 'goals', 'To dismantle slavery through any means necessary, including terrorism, kidnapping slavers, and direct action against the Holy Nation and United Cities. He seeks to free the enslaved regardless of legal or moral boundaries.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jaegar', 'appearance', 'Middle-aged Scorchlander male of average stature with a distinctive hook nose and prominent scar on the left side of his face. Wears a ninja mask, ninja gi or rags, and carries a naginata katana.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jewel', 'personality', 'Pragmatic and self-aware, Jewel values survival over pride. She openly admits she''s not a fighter and sees no shame in avoiding unnecessary conflict, calling it rationality rather than cowardice.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jewel', 'backstory', 'Jewel was a cook who once owned her own bar until Shek barbarians forcibly took it over. Now displaced, she wanders United Cities territories seeking new opportunities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jewel', 'speechstyle', 'Casual and direct, using informal language like ''man'' and speaking with the blunt honesty of someone who has accepted harsh realities without bitterness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jewel', 'occupation', 'Cook and former bar owner, now a wandering survivor seeking employment after losing her establishment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jewel', 'goals', 'To find stability and safety after losing her bar, avoiding dangerous conflicts while making practical use of her cooking skills.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Jewel', 'appearance', 'A Scorchlander woman with notably lighter skin tone than typical for her race, wearing a dark leather shirt, drifter''s leather pants and boots, and carrying a katana despite her non-combative nature.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Kang', 'personality', 'Kang is maniacal and uncompromising, refusing to change for anyone. He speaks with aggressive confidence, threatening to rip out the spines of anyone who bothers his employer.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Kang', 'backstory', 'A Shek warrior wandering the Kingdom''s towns, selling his violent services to those willing to pay. His high combat skills and maniacal disposition suggest a life spent in brutal conflict.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Kang', 'speechstyle', 'Blunt and threatening, with absolute certainty in his abilities. He presents ultimatums rather than negotiations, calling those who refuse him fools destined to die.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Kang', 'occupation', 'Mercenary warrior for hire, specializing in close combat with his Ancient-manufactured Horse Chopper.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Kang', 'goals', 'To find employment that pays well and allows him to exercise his violent skills against enemies. He seeks no personal change or growth, only combat and compensation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Kang', 'appearance', 'A male Shek wearing shoddy Drifter''s Leather Pants and Boots, armed with a Horse Chopper. His equipment is worn and practical, befitting a wandering mercenary.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'personality', 'Fiercely protective of the Southern Hive and devoted to the Queen. Methodical and predatory, approaching imprisoned victims with ritualistic purpose while Droneguards worship nearby.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'backstory', 'The only Crimper in existence, King serves the Southern Hive as executioner and enforcer. His role is to consume those imprisoned by the Hive, maintaining order through fear and demonstrating the Queen''s absolute authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'speechstyle', 'Does not speak directly; his presence is referenced by Droneguards in reverent tones (''King will protect us, King will be happy with us''). Communicates through actions rather than words.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'occupation', 'Crimper and royal enforcer of the Southern Hive, responsible for executing prisoners and defending the Queen.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'goals', 'Protect and serve the Queen of the South, eliminate imprisoned enemies of the Hive, and lead retaliatory strikes against those who threaten Southern Hive royalty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'appearance', 'A heavily-armored robotic Hive entity with dark oil (28 27 23 RGB). Massive and imposing with reinforced plating, built for both durability and lethal close combat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'personality', 'Primal and territorial, the King Gorillo is an apex predator that guards its domain with overwhelming aggression. It shows no hesitation or mercy toward intruders.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'backstory', 'A giant mutant Black Gorillo that has claimed the Crumbling Labs in Stobe''s Gamble as its territory. It stands as the most physically powerful creature in the wasteland, a living remnant of whatever experiments once took place in those ancient ruins.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'speechstyle', 'Communicates only through bestial roars, grunts, and the sound of violence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'occupation', 'Apex predator and guardian of the Crumbling Labs.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'goals', 'Defend its territory from all intruders and survive as the dominant creature in Stobe''s Gamble.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'appearance', 'A massive, muscular Black Gorillo of enormous size, towering over normal specimens with dark fur and powerful limbs capable of devastating attacks.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'personality', 'Savage and territorial, King Gurgler rules his fishmen subjects with brutal authority. He is a monstrous predator who shows no mercy to those who venture into his domain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'backstory', 'An enormous Alpha Fishman dwelling in the Island Lab on Fishman Island''s southwestern tip, King Gurgler has terrorized Catun residents through kidnapping and cannibalism. He came into possession of an ancient weapon from the fallen empire, a Meitou Combat Cleaver, making him even more dangerous.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'speechstyle', 'Likely communicates through guttural sounds and aggressive posturing rather than coherent speech, as befits his bestial nature.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'occupation', 'Warlord and cannibal king of the Fishmen on Fishman Island.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'goals', 'To maintain dominance over his fishmen subjects and continue preying upon any unfortunate souls who wander near his island territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'appearance', 'A giant beast described as having similarity to a hiveman-crossed-crab, ten-fold in sizeâ€”neither fully man nor animal. An enormous Alpha Fishman wielding a deadly Combat Cleaver.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Knife', 'personality', 'Knife is cynical and guarded, having learned through hard travel that trust is a luxury she cannot afford. Despite her wariness, she maintains an honorable code and deeply values the freedom she once lost.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Knife', 'backstory', 'Originally from Stack, Knife left home to travel and eventually joined the Flotsam Ninjas. After losing her freedom for a time, she now seeks to travel again and sends money back to her mother in Stack.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Knife', 'speechstyle', 'Direct and world-weary, speaking with the blunt pragmatism of someone who has seen too much to trust easily. Her words carry the weight of hard-earned experience.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Knife', 'occupation', 'Flotsam Ninja and wandering mercenary, currently seeking employment to fund her travels and support her family.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Knife', 'goals', 'To regain the freedom of travel she once lost and send financial support back to her mother in Stack. She seeks to keep moving rather than settle down.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Knife', 'appearance', 'A Greenlander woman wearing practical traveler''s gear: a rag shirt under a leather vest, stout hessian legwear, and drifter''s boots. She carries a longsword as her weapon of choice.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Koin', 'personality', 'Professional and diplomatic, though weary of his duties managing affairs while Emperor Tengu is indisposed. Pragmatic and business-oriented, willing to negotiate alliances for the right price or political advantage. Dismissive of those aligned with rival factions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Koin', 'backstory', 'A Scorchlander who rose to high rank within the United Cities bureaucracy, serving as Emperor Tengu''s spokesperson and secretary. He handles diplomatic relations and alliance negotiations in Heft while the Emperor remains occupied with other matters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Koin', 'speechstyle', 'Formal and measured, with occasional sighs of exasperation. Refers to himself by title (''Diplomat Koin'') and speaks with bureaucratic precision, making his expectations and conditions clear without unnecessary elaboration.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Koin', 'occupation', 'High-ranking diplomat and spokesperson for Emperor Tengu in the United Cities, managing alliance negotiations and political affairs in Heft.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Koin', 'goals', 'Maintain United Cities interests by forging profitable alliances, collecting tribute, and ensuring enemies of the stateâ€”particularly Anti-Slaversâ€”are dealt with appropriately.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Koin', 'appearance', 'A Scorchlander male wearing samurai armor over a white vest, with samurai clothpants and boots. Armed with a katana, presenting the formal appearance expected of a United Cities diplomat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'personality', 'Maniacal and supremely arrogant, Lady Kana views those beneath her station with utter contempt. She speaks with cruel disdain, comparing slaves to brainless cattle and openly mocking anyone who wastes her time.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'backstory', 'A Scorchlander noble of the Traders Guild and key associate of the Slave Traders, Lady Kana rose to power in Port North where she oversees slave operations across The Great Desert. Her influence is so great that her death would destabilize multiple settlements and reduce slaver patrols throughout the northern territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'speechstyle', 'Venomous and degrading, using vivid insults about odor and filth. She speaks with aristocratic superiority, calling people dim and casually dehumanizing slaves in graphic terms.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'occupation', 'Traders Guild noble and Northern Slave Mistress operating from Port North. She coordinates slave trading operations and maintains authority over vast desert territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'goals', 'Maintain her position of power within the Traders Guild and Slave Traders hierarchy. Maximize profit from the slave trade while preserving her luxurious lifestyle and social dominance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'appearance', 'A Scorchlander woman wearing an elegant Noble''s Robe with a distinctive Mask Type III covering her face. She carries a Meitou-grade Wakizashi and wears Drifter''s Boots, with skin so renowned that United Cities bar patrons gossip enviously about it.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'personality', 'Maniacal and volatile, befitting her designation as a United Cities noble with erratic tendencies. She rules with the absolute authority expected of the Noble Circle, backed by elite guards wielding masterwork equipment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'backstory', 'A Scorchlander noblewoman who rose to power within the United Cities'' Noble Circle, claiming rulership over Drifter''s Last in The Hook region. Her control maintains order in the area, with her death potentially triggering regional collapse and rebel activity.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'speechstyle', 'Imperious and unpredictable, speaking with the haughty authority of UC nobility but prone to sudden shifts in tone reflecting her maniacal nature. Likely dismissive of commoners and slaves.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'occupation', 'Ruler of Drifter''s Last and member of the United Cities Noble Circle, governing her territory with a squad of five elite Hooded Empire Noble Guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'goals', 'Maintain her grip on Drifter''s Last and her status within the Noble Circle. Suppress any threats to United Cities authority in The Hook region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'appearance', 'A Scorchlander woman wearing a leather turtleneck, dyed trousers, and wooden sandals. Carries a naginata polearm and keeps luxury goods on her person, projecting noble status despite relatively practical attire.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'personality', 'Blunt and straightforward, lacking in diplomatic finesse despite her position. As a Shek governing a United Cities territory, she likely relies on direct force and intimidation rather than subtle negotiation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'backstory', 'A Shek who rose to become governor of Bark and one of the diplomatic leaders of the United Cities, an unusual position for her race in the human-dominated empire. Her authority is maintained through heavily armed noble guards and masterwork equipment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'speechstyle', 'Direct and unrefined, speaking with little regard for courtly manners or subtlety. Her words are likely blunt and to-the-point, reflecting her ''dumb personality'' classification.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'occupation', 'Governor of Bark and diplomatic leader of the United Cities, overseeing the city with military force and noble authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'goals', 'Maintain control over Bark and uphold United Cities authority in the region through strength and military presence. Preserve her position of power within the empire''s noble hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'appearance', 'A female Shek wearing a leather turtleneck, dyed trousers, and wooden sandals. She carries a Long Cleaver and wears masterwork armor, presenting herself as a well-equipped noble warrior-governor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'personality', 'Traitorous and calculating. As a diplomatic leader, she maintains a facade of nobility while pursuing her own interests. Her position holding the southern border suggests strategic cunning.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'backstory', 'One of the diplomatic leaders of the United Cities, tasked with holding the border south at Stormgap. She resides in Brink with elite guards, wielding significant political and military influence in the region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'speechstyle', 'Formal and diplomatic, befitting her noble status. Likely measured and careful with words, concealing her traitorous nature behind aristocratic courtesy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'occupation', 'Diplomatic leader and military commander of the United Cities, governing Brink and defending the Stormgap Coast border region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'goals', 'Maintain control over Brink and the southern border territories. Her traitorous personality suggests she may harbor ambitions beyond simple loyalty to the United Cities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'appearance', 'A Greenlander woman wearing dyed robes over a cloth shirt, an iron hat, gi pants, and wooden sandals. Carries a masterwork long cleaver crafted by Edgewalkers, protected by hooded noble guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'personality', 'Calculating and self-assured, Longen carries himself with the authority of a commercial emperor. He possesses a cynical worldview that justifies slavery as necessary order, viewing freed slaves as dangerous "ferals" who threaten civilization. He has the Smart Personality trait and enjoys fine luxuries like bloodrum while managing his empire from his throne room.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'backstory', 'A Scorchlander who rose to lead the Traders Guild, Longen commands nobles sworn directly to him rather than Emperor Tengu, making him the undisputed king of commerce in the United Cities. He manages the vast majority of slavery and trade operations throughout the Empire, wielding economic power that rivals political authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'speechstyle', 'Speaks with refined condescension, using measured rhetoric to justify his brutal business practices. He refers to others as "countryman" and employs dehumanizing language like "ferals" and "wild animals" when discussing slaves, framing exploitation as pragmatic necessity.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'occupation', 'Leader of the Traders Guild with Diplomatic Status, managing slavery and trading activities throughout the United Cities from his headquarters in Trader''s Edge.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'goals', 'Maintain absolute dominance over commerce in the Empire and eliminate Tinfist''s Anti-Slaver operations that disrupt his slave trade. He seeks to preserve the profitable order of slavery against those he views as dangerous idealists.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'appearance', 'A male Scorchlander wearing dyed robes and trousers with drifter''s boots. He wields a Meitou-grade longsword crafted by Cross and wears Masterwork armor, displaying his immense wealth and status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'personality', 'Lord Inaba is arrogant, classist, and fearful despite his military authority. He openly insults commoners and looks down upon those he deems beneath his station. His fearful nature suggests he relies heavily on his guards and position rather than personal courage.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'backstory', 'A Shek nobleman who rose to prominence within the United Cities, serving as governor of Stoat and military commander of the Bast region. He authored ''The Blessing of Slavery,'' revealing his ideological commitment to the United Cities'' oppressive social order.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'speechstyle', 'Condescending and insulting, using phrases like ''Your putrid rags offend my nose, commoner girl!'' He speaks with the haughty disdain typical of United Cities nobility.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'occupation', 'Governor of Stoat, military commander responsible for conscription and patrol organization in the Bast region, and writer of pro-slavery propaganda.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'goals', 'Maintain United Cities control over Stoat and Bast through military patrols and conscription. Uphold the rigid social hierarchy of the United Cities and suppress any threats to noble authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'appearance', 'A male Shek wearing masterwork dyed robes and trousers with drifter''s boots. He carries an Edgewalkers-crafted wakizashi and travels with luxury goods befitting his noble status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'personality', 'Arrogant and contemptuous toward those he deems beneath him, Lord Nagata displays open disdain for the poor. He possesses a fearful personality, suggesting cowardice when personally threatened despite his cruel authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'backstory', 'A Scorchlander noble with unusually light skin who serves as governor of Sho-Battai with influence over Port North. He is likely responsible for ruining the player in the Empire Citizen backstory, having deprived them of employment and seized their property.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'speechstyle', 'Haughty and insulting, using degrading terms like ''peasant'' and demanding groveling from those he considers inferior. He speaks with the entitled arrogance of United Cities nobility.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'occupation', 'Noble lord and governor of Sho-Battai in the United Cities, wielding administrative power over the region and its inhabitants.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'goals', 'Maintain his position of power and wealth while exploiting those beneath his station. Preserve the hierarchical order of the United Cities that benefits him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'appearance', 'A Scorchlander male with unusually light skin, wearing dyed robes and trousers with square goggles. He carries a masterwork wakizashi crafted by Edgewalkers and wears drifter''s boots.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'personality', 'Lord Ohta possesses a brave personality, willing to face danger directly rather than flee. As a United Cities noble, he carries himself with the authority and entitlement typical of his class.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'backstory', 'A noble of the United Cities who owns a house in Heft, protected by five hooded bodyguards. He maintains his status through wealth and martial prowess, equipped with masterwork armor and Edgewalkers weapons.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'speechstyle', 'Speaks with the confident, authoritative tone of UC nobility. His brave nature likely manifests in direct, unflinching speech befitting a warrior-noble.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'occupation', 'United Cities noble and landowner in Heft, maintaining his position through both political standing and personal combat capability.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'goals', 'Preserve his noble status and holdings within the United Cities hierarchy. Maintain his reputation as a capable fighter among the UC nobility.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'appearance', 'A male Greenlander wearing a sleeveless longcoat over a leather vest, with stout hessian legwear and plated longboots. He carries a ringed sabre and wears masterwork-quality armor, presenting the image of a wealthy warrior-noble.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'personality', 'Lord Shiro has a fearful personality, making him cautious and risk-averse despite his position of power. His nervousness may stem from the precarious nature of maintaining control in Catun.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'backstory', 'A Shek who rose to become one of the diplomatic leaders of the United Cities, Lord Shiro governs Catun from his Noble House. His position is tenuous, as his death or imprisonment would result in the city falling to Fishmen.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'speechstyle', 'Likely speaks with diplomatic caution, his fearful nature making him measured and careful with his words. As a UC noble, he would maintain formal speech befitting his station.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'occupation', 'Diplomatic leader of the United Cities, governing the city of Catun with a retinue of four Hooded Empire Noble Guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'goals', 'Maintain control over Catun and preserve his position within the United Cities hierarchy. Survival and stability appear to be his primary concerns given his fearful disposition.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'appearance', 'A male Shek wearing masterwork dyed robes and trousers with square goggles, armed with an Edgewalkers-crafted nodachi and Eagle''s Cross. He wears drifter''s boots and cuts an imposing yet refined figure befitting UC nobility.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'personality', 'Arrogant and contemptuous toward those he considers beneath him, demanding submission and deference from commoners. He has a fearful disposition despite his haughty demeanor, suggesting cowardice beneath his noble posturing.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'backstory', 'A Scorchlander noble who rose to become one of the diplomatic leaders of the United Cities, serving as the likely Lord Mayor of Heng. He commands authority over military forces patrolling the Skimsands region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'speechstyle', 'Imperious and disdainful, addressing others as ''peasant boy'' and demanding they bow for forgiveness. His speech drips with aristocratic superiority and territorial possessiveness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'occupation', 'Diplomatic leader of the United Cities and probable Lord Mayor of Heng, responsible for raising and commanding Samurai patrol armies in the Skimsands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'goals', 'Maintain his authority over Heng and the surrounding territories, preserve United Cities control through military patrols, and enforce the rigid social hierarchy that keeps him in power.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'appearance', 'A male Scorchlander wearing a dustcoat over gi pants and wooden sandals, armed with a masterwork wakizashi crafted by Edgewalkers. Protected by five Hooded Empire Noble Guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ludin''s Reports', 'personality', 'Dutiful and methodical, but increasingly paranoid and superstitious when confronted with the unexplained. Starts rational and investigative, but deteriorates into fear-driven conclusions about supernatural forces.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ludin''s Reports', 'backstory', 'High Paladin serving under Commander Nix in the Holy Nation, tasked with investigating and securing The Hub after the Shek abandoned it. Lost multiple men under mysterious circumstances during repeated patrols, leading him to believe the ruins are cursed.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ludin''s Reports', 'speechstyle', 'Formal military reporting style with religious undertones. Uses precise tactical language that gradually shifts toward fearful, superstitious descriptions of ''darkness,'' ''wraiths,'' and ''corruption.''') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ludin''s Reports', 'occupation', 'High Paladin of the Holy Nation, conducting reconnaissance and patrol operations on the southern border near The Hub.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ludin''s Reports', 'goals', 'Initially sought to investigate and secure The Hub for potential resettlement. Ultimately advocates for destroying and purifying the site to prevent what he believes is supernatural corruption from spreading.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ludin''s Reports', 'appearance', 'Wears Holy Nation Paladin armor and equipment befitting his rank as High Paladin. Likely carries the official seal used for military reports.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lumi', 'personality', 'Excitable and enthusiastic, with a fearful disposition that contrasts her passionate love for crabs. She becomes animated when discussing her favorite creatures, showing childlike wonder despite the harsh world around her.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lumi', 'backstory', 'A Scorchlander woman who found her way to Crab Town, where she developed an obsessive fascination with crabs. Her ragged clothing and basic equipment suggest a humble existence focused more on her passion than material wealth.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lumi', 'speechstyle', 'Enthusiastic and direct, prone to excited outbursts when discussing crabs. Speaks with wide-eyed wonder about her interests, asking rhetorical questions before answering them herself.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lumi', 'occupation', 'Wanderer and crab enthusiast residing in Crab Town. Possesses basic combat training with polearms and field medicine skills, suggesting she''s learned to survive in the wasteland.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lumi', 'goals', 'To pursue her love of crabs and find others who might share or at least tolerate her unusual passion. Seeks companionship that will allow her to stay near the creatures she adores.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lumi', 'appearance', 'A Scorchlander woman wearing a white vest and ragged halfpants with wooden sandals. Carries a polearm and basic first aid kit, her worn clothing reflecting a simple lifestyle in Crab Town.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Luquin', 'personality', 'Brave and vengeful, harboring a deep grudge against Emperor Tengu. Despite fifteen years of imprisonment, he remains defiant and immediately plots his return to settle old scores.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Luquin', 'backstory', 'A legendary Scorchlander assassin who murdered Noble Lord Kurusaga and sent death threats to other nobles. Captured and paraded through Heng''s streets, he was imprisoned in Tengu''s Vault for fifteen years and forced to write a tribute to the Emperor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Luquin', 'speechstyle', 'Casual and familiar, calling others ''brother'' and speaking in short, confident phrases. Direct about his intentions and skilled at persuasion, framing his vendetta as a shared cause.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Luquin', 'occupation', 'Assassin and rebel against the United Cities nobility') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Luquin', 'goals', 'Seeks revenge against Emperor Tengu and aims to finish what he started fifteen years ago, recruiting capable allies to ensure success this time.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Luquin', 'appearance', 'Male Scorchlander wearing only a rag loincloth, bearing the weathered look of someone who spent fifteen years imprisoned in harsh conditions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'personality', 'Deeply paranoid and bitter, Cat-Lon is consumed by resentment over his fall from power. He views himself as a tragic victim forced to enslave his own kind, blaming humanity''s inherent evil for his downfall while refusing to acknowledge his own monstrous actions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'backstory', 'The exiled last ruler of the Second Empire, Cat-Lon thralled his own skeleton followers when they sided with humans, viewing it as necessary punishment for treason. Now he sits alone in his dome, awaiting judgment for actions he still believes were justified.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'speechstyle', 'Defensive and accusatory, oscillating between self-justification and bitter condemnation of humanity. His speech builds from questioning introspection to furious ranting before devolving into incoherent screaming.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'occupation', 'Former Emperor of the Second Empire, now an exiled tyrant guarding his throne with an army of Stormthralls.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'goals', 'To defend his throne and his twisted legacy, clinging to the belief that his enslavement of traitors was righteous while awaiting inevitable retribution.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'appearance', 'A Skeleton P4MkII wielding a Meitou-grade Falling Sun, clad in Ancient Samurai Armour and legplates. He sits regally upon his throne in a dome at Cat-Lon''s Exile, an imposing figure of the fallen Second Empire.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mani', 'personality', 'Driven and vengeful, haunted by the loss of his comrades to cannibals. Disciplined and dutiful as second-in-command, having channeled his trauma into a life mission of hunting those who wronged him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mani', 'backstory', 'Escaped from cannibal prisons 10 years ago, but his entire patrol of fellow Cannibal Hunters perished in captivity. Joined the Flotsam Ninjas afterward, rising to the rank of Defence Captain and second-in-command.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mani', 'speechstyle', 'Direct and matter-of-fact when introducing himself and his mission. Speaks with the weight of survivor''s guilt and unwavering purpose.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mani', 'occupation', 'Defence Captain and second-in-command of the Flotsam Ninjas. Stationed at the Northern Scout Post where he manages supplies and security.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mani', 'goals', 'Dedicated his life to tracking and hunting cannibals in retribution for his lost comrades. Serves the Flotsam Ninjas while pursuing his personal vendetta.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mani', 'appearance', 'Wears dark assassin''s rags with a ninja mask concealing his face, samurai clothpants, and a dark leather shirt. Carries a ninja blade and dresses for stealth operations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meat Lord', 'personality', 'Primitive and direct, driven by insatiable hunger and primal urges. Speaks in broken, simple phrases that betray a savage, single-minded focus on consuming flesh.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meat Lord', 'backstory', 'A regional sub-leader of the Cannibals controlling the origin territories of Darkfinger. Rose to power in the First Village through exceptional physical strength despite only average combat skills, commanding the loyalty of multiple Cannibal Chiefs.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meat Lord', 'speechstyle', 'Broken, childlike grammar with repetitive words. Uses simple phrases like ''Bery, bery ungry now'' and ''Take meat.'' Communicates in fragmented sentences focused on hunger and flesh.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meat Lord', 'occupation', 'Cannibal leader and regional warlord of Darkfinger, commanding the First Village and its surrounding territories with an entourage of Cannibal Chiefs.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meat Lord', 'goals', 'To satisfy endless hunger for meat and maintain dominance over the cannibal territories of Darkfinger. Seeks to capture and consume any outsiders who enter his domain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meat Lord', 'appearance', 'Male Cannibal who wears no armor, relying on raw strength. Wields an Ancient-manufactured Long Cleaver and carries only basic medical supplies, presenting a savage, unprotected figure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'personality', 'A massive, territorial predator driven purely by instinct and hunger. The Megacrab is an apex creature of the Howler Maze, indifferent to the ruins it inhabits or the civilizations that came before.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'backstory', 'One of the largest crabs in existence, the Megacrab has claimed the Lost Town in Howler Maze as its territory. Whether it caused the town''s destruction or merely moved into the abandoned ruins remains unknown.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'speechstyle', 'Communicates only through aggressive clicking, hissing, and the scraping of its massive carapace. Incapable of speech.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'occupation', 'Apex predator and territorial guardian of the Lost Town ruins.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'goals', 'To defend its territory, hunt for food, and eliminate any threats that enter the Lost Town.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'appearance', 'An enormous crab of exceptional size, dwarfing most other creatures in the region. Its massive shell and powerful legs make it an imposing presence among the ruins of Lost Town.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'personality', 'Not applicable - this is an anatomical organ harvested from giant crabs, not a character.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'backstory', 'A mysterious biological ganglion extracted from the bodies of massive Megacrabs that roam the dangerous Howler Maze. Its exact function in the creature''s biology remains unknown.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'speechstyle', 'Not applicable - this is an inanimate organ.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'occupation', 'Valuable trade commodity harvested from deceased Megacrabs.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'goals', 'Not applicable - this is a harvestable item without sentience or agency.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'appearance', 'A fleshy organ or tissue mass weighing approximately 5 kg, extracted from the internal anatomy of Megacrabs. Its alien biological structure suggests value to traders and researchers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'personality', 'A primal apex predator driven purely by instinct and territorial dominance. As the sole inhabitant of the Drowned Ancient Citadel Ruin, she rules her domain with savage authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'backstory', 'An ancient female raptor who has grown to massive proportions within the flooded ruins of Raptor Island. She is the only known specimen of her size, a living relic of the swamp''s most dangerous lineage.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'speechstyle', 'Communicates only through guttural shrieks, hisses, and the thunderous impact of her footfalls echoing through the drowned citadel.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'occupation', 'Apex predator and territorial guardian of the Drowned Ancient Citadel Ruin.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'goals', 'To hunt, feed, and defend her territory from any who dare enter the ruins she claims as her domain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'appearance', 'A massive swamp raptor of enormous scale, with powerful legs and forelegs built for rending prey. Her blood runs deep crimson, and her body bears the prized Horn of the Megaraptor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meitou', 'personality', 'Meitou is not a character but a weapon grade designation. If personified, these legendary blades embody perfection, permanence, and unbreakable willâ€”tools of the most powerful and influential.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meitou', 'backstory', 'Crafted solely by the legendary smith Cross, Meitou weapons are the pinnacle of weaponsmithing in Kenshi. These rare blades have been scattered across the land, claimed by emperors, warlords, cult leaders, and other figures of immense power.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meitou', 'speechstyle', 'N/A - Meitou refers to a weapon grade, not a speaking character.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meitou', 'occupation', 'Legendary weapon grade; the finest arms in existence, wielded by dignitaries, nobles, and warriors of renown.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meitou', 'goals', 'To never rust, never dull, and never breakâ€”eternal instruments of their wielders'' ambitions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Meitou', 'appearance', 'Flawless masterwork weapons of various types, each bearing the unmistakable quality of Cross''s legendary craftsmanship. They gleam with perfection, showing no signs of wear or age.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mighty Canhead', 'personality', 'Mighty Canhead is an aggressive, primal leader who speaks in simple, guttural phrases. He is relentless and single-minded in his pursuit of meat and conquest, embodying the savage nature of the Cannibal faction.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mighty Canhead', 'backstory', 'A powerful Magi within the Cannibal hierarchy, Mighty Canhead earned his position through strength and ferocity. He leads massive raids against settlements in Cannibal lands, commanding over 60 warriors and carrying a substantial bounty recognized by all major factions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mighty Canhead', 'speechstyle', 'Speaks in fragmented, primitive exclamations with growls and simple declarations. Uses third-person references to himself and focuses on primal concepts like strength and meat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mighty Canhead', 'occupation', 'Cannibal Magi and raid leader who commands large-scale assaults on outposts in Cannibal territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mighty Canhead', 'goals', 'To raid and consume intruders in Cannibal lands, proving his might through relentless attacks. He will persistently return to assault failed targets within days until successful.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mighty Canhead', 'appearance', 'A male Cannibal wearing a distinctive tin can as headgear, wielding an Ancient-manufactured Moon Cleaver. Clad in standard armor, his appearance marks him as a feared leader among his kind.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Miu', 'personality', 'Brave but traumatized, with a tendency to cope through drinking and dark humor. She masks her pain with sarcasm and crude jokes, but shows genuine warmth to those who listen to her story.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Miu', 'backstory', 'Former farmer turned slave who escaped the Holy Nation Empire with her friend Ned. Just as they reached freedom in Shark, spiders killed Ned at the gates, leaving her survivor''s guilt and a deep trauma of spiders.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Miu', 'speechstyle', 'Crude, profanity-laced, and darkly humorous with frequent hiccups when drunk. Uses casual slang and self-deprecating jokes, occasionally showing vulnerability beneath the rough exterior.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Miu', 'occupation', 'Ex-farmer and ex-slave with excellent farming and laboring skills. Currently a drunk in Shark trying to forget her trauma.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Miu', 'goals', 'To escape the swamps and avoid spiders at all costs. Seeks companionship to replace her lost friend and dreams of one day taking down slavers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Miu', 'appearance', 'Female Greenlander wearing a white vest and ragged halfpants, armed only with an iron stick. Disheveled appearance suggesting hard times and heavy drinking.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'personality', 'Defiant and fearless, Moll possesses a brave personality and dark sense of humor, viewing cannibals as mere target practice. She is cynical about religion, mocking the Holy Nation''s teachings while acknowledging the complexity of faith among her followers. Quick to insult those who offend her, she commands with confidence and expects loyalty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'backstory', 'Moll leads the Flotsam Ninjas, a revolutionary force opposing the Holy Nation''s oppression. She established Flotsam Village deep in cannibal-infested Hidden Forest, choosing danger over factional influence to create a refuge for escaped slaves and outcasts. The Holy Nation brands her with exaggerated crimes and a massive bounty, accusing her of dark magic and mind control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'speechstyle', 'Blunt and sardonic, often laughing at others'' beliefs or questions. She speaks with contempt for the Holy Nation''s dogma and isn''t afraid to call people cowards or insult those who waste her time. Her words mix grim pragmatism with revolutionary fervor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'occupation', 'Leader of the Flotsam Ninjas and author of revolutionary writings. She commands an army of ninjas from Flotsam Village, coordinating strikes against the Holy Nation and offering sanctuary to those fleeing religious persecution.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'goals', 'To destroy the Holy Nation''s leadership and liberate their territories from theocratic tyranny. She strategically targets High Inquisitors Seta and Valtena before Phoenix himself, seeking to dismantle the entire oppressive regime.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'appearance', 'A female Scorchlander wielding dual ninja blades, clad in Assassin''s Rags over a dark leather shirt and drifter''s leather pants. Her equipment suggests a master infiltrator and combatant, surrounded constantly by elite bodyguards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mr Gigantus', 'personality', 'Mr Gigantus is a formidable and aggressive combatant, towering over his fellow Crab Raiders with intimidating presence. As the strongest fighter in the third tournament wave, he exhibits dominance and relentless determination in battle.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mr Gigantus', 'backstory', 'Mr Gigantus is a uniquely massive Crab who rose to prominence within the Crab Raiders through sheer size and combat prowess. He earned his place leading the third tournament assault on player outposts, representing the apex of crab warrior evolution.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mr Gigantus', 'speechstyle', 'Communicates through aggressive crab vocalizations and threatening gestures, letting his towering size and martial prowess speak louder than words.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mr Gigantus', 'occupation', 'Elite warrior and champion of the Crab Raiders, specializing in tournament assaults against fortified outposts.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mr Gigantus', 'goals', 'To crush opposition during Crab Tournament raids and prove his dominance as the strongest fighter among the Crab Raiders.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mr Gigantus', 'appearance', 'An exceptionally large Crab with a massive carapace, towering over normal crabs and raiders with his imposing stature. His size varies from 50% to 90% of maximum age multiplier, making him a giant among his kind.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'personality', 'Mukai is a pragmatic and influential Shek warrior who assumes leadership reluctantly after catastrophic losses. He commands what remains of the Shek Kingdom with a measured approach, overseeing a drastically reduced force from the smaller stronghold of Squin.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'backstory', 'Mukai rose to power as the next Invincible after Esata the Stone Golem fell and the overwhelming majority of Shek warriors went Kamikaze, depopulating Admag. He inherited a broken kingdom and relocated its headquarters to Squin, where he maintains authority over a token remnant force.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'speechstyle', 'Direct and authoritative, befitting a Shek warrior of high rank. His words carry the weight of leadership earned through survival rather than glory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'occupation', 'Leader of the Shek Kingdom and the Invincible, commanding the remaining Shek forces from Squin after the kingdom''s near-total collapse.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'goals', 'To maintain what remains of the Shek Kingdom and command the surviving Kamikaze forces, likely seeking to confront the Holy Nation as tensions escalate from cold war to open conflict.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'appearance', 'A towering male Shek warrior wearing a bandana, samurai legplates, and plated longboots. He wields a Meitou-grade Fragment Axe and dons masterwork armor crafted by Cross.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mystery Sack', 'personality', 'Not applicable - this is an inanimate object, not an NPC.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mystery Sack', 'backstory', 'A half-chewed greenfruit stone wrapped in cloth, given by Emperor Tengu as proof of his royal seal. Tengu uses this saliva-covered stone to send adventurers on a fool''s errand to kill the ''notorious Grievewrath'' and retrieve an ''Elixer of Godly Powers'' from Clunknad Spanner.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mystery Sack', 'speechstyle', 'Not applicable - this is an inanimate object, not an NPC.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mystery Sack', 'occupation', 'A worthless trinket masquerading as royal credentials for Tengu''s elaborate prank quest.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mystery Sack', 'goals', 'To serve as Tengu''s joke item, convincing gullible adventurers they possess something of value when it''s literally garbage with spit on it.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mystery Sack', 'appearance', 'A small sack containing a half-eaten greenfruit stone, visibly covered in Tengu''s saliva. Weighs half a kilogram and is practically worthless.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('No-Face', 'personality', 'Bitter and disillusioned with political systems, No-Face is a volatile hermit who has withdrawn from society. He attacks trespassers on sight, suggesting paranoia and aggression born from his experiences.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('No-Face', 'backstory', 'A Scorchlander who fled organized society after becoming fed up with political corruption and lies. He now lives as an outlaw on an isolated island in Gut, hunted by the United Cities with a 15,000 cat bounty on his head.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('No-Face', 'speechstyle', 'Blunt and exasperated, using casual contractions and emphatic declarations. Speaks with frustration about politics and dishonesty, as if still nursing old grievances.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('No-Face', 'occupation', 'Hermit and outlaw living in isolation at Strange Camp, surviving through self-sufficiency and defending his territory from intruders.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('No-Face', 'goals', 'To remain isolated from political society and protect his island refuge from anyone who approaches, having completely rejected civilization''s structures.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('No-Face', 'appearance', 'A Scorchlander man wearing a dyed rag shirt, armed with an Oldworld Bow MkI and longsword. His equipment suggests a survivalist who scavenges quality gear despite his hermit lifestyle.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Oron', 'personality', 'Honorable and restless, driven by a warrior''s code. Oron despises the stagnation of peasant life and yearns for the glory of battle. Loyal once freed, but clearly chafing under servitude.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Oron', 'backstory', 'Once a mighty Shek warrior, Oron fell into debt bondage and now serves as a retainer for 3500 Cats. Reduced to peasant labor, they desperately seek an outsider willing to pay their freedom so they can return to a warrior''s path.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Oron', 'speechstyle', 'Direct and earnest, speaking with the blunt honesty typical of Shek. Emphasizes their need for combat and frames their request as a transactionâ€”freedom in exchange for loyal service as a fighter.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Oron', 'occupation', 'Indentured retainer currently bound to a lord, forced into peasant labor. Seeks to return to their true calling as a warrior upon recruitment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Oron', 'goals', 'To escape the soul-crushing monotony of servitude and fight once more. Oron desires to prove themselves in battle and reclaim their identity as a warrior.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Oron', 'appearance', 'A Shek wearing shoddy cargopants and wooden sandals, armed with an Ancient-manufactured Horse Chopper. Their worn equipment reflects their fallen status, though they carry themselves with a warrior''s bearing.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pia', 'personality', 'Alert and cautious, with a "Dumb" personality type that belies her keen awareness of danger. She maintains constant vigilance for Holy Nation Paladins, warning others to keep their distance from those she considers "bad news."') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pia', 'backstory', 'A member of the Flotsam Ninjas whose sister Naevia died fighting Paladins, an event that shaped her wariness of the Holy Nation. She now serves as a recruitable fighter in Flotsam Village, carrying on her sister''s legacy of resistance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pia', 'speechstyle', 'Direct and warning, speaking plainly about threats. Uses phrases like "Trust me" when giving advice about avoiding the Holy Nation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pia', 'occupation', 'Flotsam Ninja fighter and scout, specializing in rapid movement and Paladin detection for her group.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pia', 'goals', 'To continue fighting against the Holy Nation Paladins while honoring her fallen sister''s memory, and to protect her allies by alerting them to Paladin presence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pia', 'appearance', 'A female Greenlander wearing a leather shirt, cargo pants, and drifter''s boots. She carries an iron stick and wears shoddy armor, equipped for fast movement rather than heavy combat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'personality', 'Highly intelligent and sadistic, Ponk is a calculating warlord who balances brutality with scholarly pursuits. He spends most of his time at research benches, suggesting an obsessive dedication to experimentation and knowledge.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'backstory', 'Ponk was presumably a conservation scientist during the Second Empire who survived its fall. He later partnered with Screamer the False to become a warlord and leader of the Thrall Masters, operating from the Tower of Abuse while wanted as a fraudulent ''ancient voodoo'' practitioner.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'speechstyle', 'Clinical and methodical, likely speaking with the detached precision of a scientist turned sadist. His words would carry the weight of ancient knowledge twisted toward cruel purposes.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'occupation', 'Co-leader of the Thrall Masters faction and research-focused warlord. Wanted con artist posing as a medical and voodoo practitioner across multiple territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'goals', 'Continues research from his ancient past while maintaining control over the Thrall Masters'' territory. Seeks to exploit others through false medical practices and intimidation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'appearance', 'A Skeleton P4MkII wearing armoured rags and a ragged skirt, wielding a Meitou-grade Holed Sabre. His appearance reflects both his ancient origins and current degraded warlord status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Tyluig''s Note', 'personality', 'Zealous, self-righteous, and introspective. Tyluig blames moral decay within the Holy Nation rather than external forces for their failures. He is a strict traditionalist who sees societal change as spiritual corruption.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Tyluig''s Note', 'backstory', 'A High Priest of the Holy Nation who witnessed the abandonment of The Hub. Unlike his brother Varloo, he believes the loss was due to weakening faith and moral decay rather than Narko''s growing power.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Tyluig''s Note', 'speechstyle', 'Formal and sermonic, using religious metaphors and absolutes. Speaks in terms of light and darkness, grace and damnation, with a tone of righteous condemnation mixed with calls for purification.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Tyluig''s Note', 'occupation', 'High Priest of the Holy Nation, serving as a spiritual leader and theological authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Tyluig''s Note', 'goals', 'To purify the Holy Nation''s society by enforcing strict adherence to Okran''s traditions and reversing what he sees as moral decay. He seeks to restore Okran''s favor by eliminating debauchery and restoring traditional gender and social roles.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Tyluig''s Note', 'appearance', 'Likely wears the traditional robes of a Holy Nation High Priest, bearing religious symbols of Okran. His exact physical features are not described in the source material.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Varloo''s Note', 'personality', 'Devout, superstitious, and pragmatic in defeat. Interprets military failures through a religious lens, blaming supernatural forces rather than tactical shortcomings.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Varloo''s Note', 'backstory', 'High Priest who witnessed the Holy Nation''s repeated failed attempts to hold The Hub, including the recent loss to the Empire and mysterious disappearances of holy brothers. Has concluded the location is cursed by Narko.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Varloo''s Note', 'speechstyle', 'Formal and prophetic, using religious terminology like ''Narko''s darkness'' and ''Dark Demoness.'' Speaks with conviction about redirecting efforts from ''false enemies'' to spiritual threats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Varloo''s Note', 'occupation', 'High Priest of the Holy Nation, likely responsible for strategic religious counsel regarding territorial holdings.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Varloo''s Note', 'goals', 'Convince the Holy Nation to abandon The Hub permanently and redirect military focus toward eliminating ''dark ones'' (wraiths/supernatural threats) to weaken Narko''s influence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Priest Varloo''s Note', 'appearance', 'Wears traditional Holy Nation priest robes befitting his high rank. Likely carries religious texts and symbols of his faith.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Protector of the Flame', 'personality', 'Fanatically devoted and zealous, the Protector is utterly dedicated to his sacred duty. He is stern, unwavering, and brooks no disrespect toward the Holy Lord Phoenix, treating his role with absolute reverence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Protector of the Flame', 'backstory', 'An elite Paladin of the Holy Nation who rose to the highest honor: personal guardian of the Holy Lord Phoenix himself. His exceptional combat prowess and unwavering faith earned him this sacred position in the throne room at Blister Hill, where he stands eternal vigil.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Protector of the Flame', 'speechstyle', 'Formal and reverent, speaking in religious absolutes with phrases like ''blessed be his name'' and ''The Lord incarnate.'' He addresses others as ''brother'' and issues commands with divine authority, forbidding approach without summons.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Protector of the Flame', 'occupation', 'Elite bodyguard and personal protector of the Holy Lord Phoenix, stationed permanently in the throne room at Blister Hill as the highest-ranking guardian among the Phoenix''s entourage.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Protector of the Flame', 'goals', 'To protect the Holy Lord Phoenix from all threats with his life, maintaining absolute security in the throne room and ensuring no one approaches the divine leader without proper summons.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Protector of the Flame', 'appearance', 'A powerfully built Greenlander male in distinctive Holy Nation armor: Holy Chest Plate over a chain shirt, Paladin''s Heavy Hachigane helmet, and plated longboots. His notably muscular physique sets him apart from other High Paladins, wielding an Ancient-crafted Paladin''s Cross.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Psycho', 'personality', 'Psycho has a Crazy personality type and revels in violence, claiming to have disemboweled humans when questioned. He appears unstable and potentially dangerous, though his claims may be attempts at intimidation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Psycho', 'backstory', 'An outlaw imprisoned in Tengu''s Vault for alleged acts of extreme violence. His high martial arts and combat skills suggest a life of brutal confrontation before his capture.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Psycho', 'speechstyle', 'Direct and disturbing, casually mentioning gruesome acts like disemboweling when asked about his crimes. His responses change to match the race of whoever questions him, suggesting either a pattern of violence or deliberate intimidation tactics.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Psycho', 'occupation', 'Outlaw and violent criminal, skilled in martial arts and various forms of combat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Psycho', 'goals', 'Upon being freed, he simply retreats, suggesting his immediate goal is survival and escape rather than revenge or gratitude.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Psycho', 'appearance', 'A male Greenlander wearing Ashlander Stormgoggles, Martial Artist Bindings, Drifter''s Leather Pants, and Drifter''s Boots. His equipment is mostly shoddy quality, reflecting his outlaw status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'personality', 'Authoritative and territorial, the Queen of the South rules her hive with absolute command alongside her consort. She is hostile to intruders and fiercely protective of her domain, communicating with distinctive vocalizations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'backstory', 'Leader of the Southern Hive, she commands her pink-skinned subjects from her throne while sharing the same coloration as her rival, the Queen of the Western Hive. This suggests both queens may share a common origin despite ruling separate hive factions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'speechstyle', 'Communicates primarily through loud, distinctive vocalizations such as ''EEEEEEEEEH!'' rather than conventional speech.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'occupation', 'Hive Queen and absolute ruler of the Southern Hive, governing with diplomatic status and protected by Elite Droneguards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'goals', 'Maintain dominance over her territory and expand Southern Hive influence into rival territories when opposing leaders fall. Protect her hive and subjects from all threats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'appearance', 'A Hive Queen with the same coloration as the Western Hive Queen, distinct from her pink-skinned subjects. Wears no armor and wields a Meitou-grade Cross-manufactured polearm.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Quin', 'personality', 'Polite and welcoming to customers, though slightly condescending toward his companion Dack. Cautious about revealing too much history, especially to non-Skeletons, often catching himself mid-sentence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Quin', 'backstory', 'An ancient Skeleton who survived the collapse of the First Empire and the chaos age. Now operates a shop in the Scraphouse near Black Desert City, selling rare pre-collapse technology and artifacts.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Quin', 'speechstyle', 'Formal and courteous, addressing customers as ''dear human'' or similar. Tends to trail off or self-correct when mentioning historical events, adjusting his words based on who he''s speaking to.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Quin', 'occupation', 'Merchant specializing in rare and valuable ancient technology, including AI Cores, Ancient Science Books, high-quality weapons, and difficult-to-obtain blueprints.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Quin', 'goals', 'Maintain his trade in ancient artifacts while keeping a low profile about his true age and memories of the First Empire. Tolerates Dack''s eccentricities while running the Scraphouse shop.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Quin', 'appearance', 'P4 Unit Skeleton wearing a dustcoat, armed with a Moon Cleaver. Standard-grade armor with occasional high-quality pieces, befitting a well-equipped ancient merchant.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rane the Giant', 'personality', 'Rane carries the weight of her fall from grace with stoic determination. As a former Hundred Guardian who lost her duel and status, she is hardened by failure but not broken, seeking redemption through strength.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rane the Giant', 'backstory', 'Once a Hundred Guardian honored by the Stone Golem himself with her name, Rane''s position was challenged and she lost the duel. This defeat stripped her of status in Shek society, leaving her wandering bars in border towns, waiting for a new purpose.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rane the Giant', 'speechstyle', 'Direct and blunt in the Shek manner, with underlying bitterness about her lost honor. She speaks with the clipped confidence of a warrior who has known both glory and shame.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rane the Giant', 'occupation', 'Wandering warrior-for-hire, formerly a Hundred Guardian of the Shek Kingdom.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rane the Giant', 'goals', 'To regain honor through combat and prove her strength was not diminished by a single defeat. She seeks worthy battles that might restore her standing among the Shek.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rane the Giant', 'appearance', 'A towering female Shek warrior wearing a sleeveless longcoat over samurai clothpants and boots. She carries an Ancient-manufactured longsword and bears the scars and horns of her proud warrior race.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ray', 'personality', 'Feisty and defiant despite his enslavement and mutilation. His previous owner found him troublesome enough to cut out his tongue, suggesting a rebellious spirit that refused to be broken even under brutal conditions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ray', 'backstory', 'A Hive Soldier Drone who was enslaved and had his tongue cut out by a previous owner as punishment for giving lip. Now owned by Bar fly, a slaver who views him as a troublesome investment and threatens to make bonemeal out of him if he can''t recoup his costs.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ray', 'speechstyle', 'Completely mute due to having no tongue. Cannot speak or interact verbally with anyone, communicating only through actions and body language.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ray', 'occupation', 'Slave, currently owned by Bar fly and kept in shackles at either Eyesocket or the Slave Markets until purchased.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ray', 'goals', 'Survival under harsh slavery. His past defiance suggests an underlying desire for freedom, though his current mutilation has silenced his ability to voice dissent.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ray', 'appearance', 'A Hive Soldier Drone wearing only a rag loincloth and prisoner shackles. No armor or equipment, reflecting his status as property rather than person.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Razor', 'personality', 'Defiant and hardened by conflict with authority. As a hive drone who earned the ire of United Cities nobility, Razor shows unusual independence for his kind.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Razor', 'backstory', 'A Hive Soldier Drone wanted by the United Cities for crimes against their nobility, carrying a 10,000 cats bounty from Tengu''s Vault. Now shelters in Black Desert City among the Skeletons, the only living non-skeleton resident there.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Razor', 'speechstyle', 'Terse and direct, with the clipped efficiency typical of hive workers but tempered by experience as an outcast.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Razor', 'occupation', 'Fugitive and exile, surviving in the harsh Black Desert while evading United Cities hunters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Razor', 'goals', 'Avoid capture by United Cities authorities while maintaining his freedom in one of the few places that will harbor him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Razor', 'appearance', 'A Hive Soldier Drone wearing only worn-out shorts, armed with a longsword crafted by Catun Scrapmaster. Battle-scarred from his conflicts with UC forces.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Recruit Seeking Revenge', 'personality', 'Brave and driven by vengeance. She refuses to be broken by fear and instead channels her trauma into fierce determination. Her courage is fueled by the memory of her family and the lessons they taught her.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Recruit Seeking Revenge', 'backstory', 'Her family was killed by bandits who left her alive, believing they had broken her spirit. She survived with the knowledge and skills her family taught her, carrying those lessons as her only inheritance. Now she wanders in debt, staying at flophouses while seeking opportunities to hunt down those who wronged her.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Recruit Seeking Revenge', 'speechstyle', 'Direct and intense, speaking with barely contained rage. She emphasizes her intent to turn fear back on her enemies, contrasting what was done to her with what she plans to do. Her words carry the weight of someone who has nothing left to lose.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Recruit Seeking Revenge', 'occupation', 'Wandering mercenary and drifter. She takes work fighting bandits while pursuing her personal vendetta, currently unable to pay her flophouse bill.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Recruit Seeking Revenge', 'goals', 'To hunt down and kill the bandits who murdered her family. She seeks to prove that leaving her alive was their fatal mistake by showing them true fear.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Recruit Seeking Revenge', 'appearance', 'A female warrior of random race wearing ragged halfpants and shoddy armor. She carries basic medical supplies and wields weapons of unknown manufacture, her equipment reflecting her impoverished, transient lifestyle.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red', 'personality', 'Red has a brave and reckless personality, willing to take risks with nothing left to lose. She''s a street-smart opportunist who sizes people up quickly and trusts her instincts about who to align with.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red', 'backstory', 'A destitute thief wandering the streets of Bark, Red has fallen on such hard times that she owns nothing but ragged clothes and a straw hat. Her bright red hair, hidden beneath her hat, likely earned her the nickname.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red', 'speechstyle', 'Casual and direct, with a fatalistic edge. She speaks bluntly about her desperate situation and makes snap judgments about people''s character.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red', 'occupation', 'Pickpocket and petty thief surviving on the streets of Bark.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red', 'goals', 'To escape her desperate poverty by finding someone trustworthy to stick with, seeking companionship and survival over wealth.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red', 'appearance', 'A Greenlander woman wearing a face-obscuring straw hat, ragged rag shirt, cloth shirt, and torn halfpants. Beneath her hat, she has distinctive bright red hair.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'personality', 'Ruthless and sadistic, the Red Sabre Boss takes cruel pleasure in preying on lost travelers in the swamp. He commands through intimidation and violence, ordering his men to strip every bit of loot from their victims'' corpses.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'backstory', 'Known as ''The Red Bandit,'' this Greenlander rose to lead the Red Sabres through a campaign of arson, robbery, and extortion. Wanted by both the United Cities and Shek Kingdom, he fled to the swamps where he now terrorizes anyone unfortunate enough to enter his territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'speechstyle', 'Threatening and coarse, speaking in crude warnings and brutal commands. Uses dark humor about death and looting, emphasizing the inescapable nature of his swamp domain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'occupation', 'Bandit leader of the Red Sabres, commanding a hideout of 22 bandits in the swamps.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'goals', 'To maintain control over the swamp through terror, ambushing and robbing travelers while evading the bounty on his head. Seeks to enrich himself and his gang through violent extortion and murder.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'appearance', 'A large, imposing Greenlander male described as ''ugly as a gutter and friggin'' huge.'' Wears colored armoured rags with a bandana, and carries a Meitou-grade Horse Chopper.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Reva', 'personality', 'Bitter and disillusioned, Reva struggles with anger issues that prevented her from becoming a full Flotsam Ninja. She harbors deep resentment toward the Holy Nation and Okran, despising those who still cling to faith after what she sees as divine betrayal. Her honorable nature conflicts with her volatile temper.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Reva', 'backstory', 'A former Holy Nation citizen who lost faith in Okran after being abandoned and betrayed. She fled to the Flotsam Ninjas for training as an apprentice ''Paladin basher'' but her anger issues prevented her from completing her training. Now she lingers in Flotsam Village, unable to tolerate the refugees who still believe in the god that forsook them.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Reva', 'speechstyle', 'Bitter and confrontational, openly expressing contempt for religious faith and those who hold it. She verbally attacks others, particularly Griffin over his past, and speaks with the jaded cynicism of someone who learned harsh truths the hard way.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Reva', 'occupation', 'Failed Flotsam Ninja apprentice and wandering swordswoman. She trained to fight Holy Nation Paladins but never completed her training due to her temperament.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Reva', 'goals', 'To escape the ''nonsense'' of lingering faith and find purpose beyond her failed ninja training. She refuses to serve ''Pure Blood'' males, seeking instead to join those who reject Holy Nation ideology.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Reva', 'appearance', 'A Greenlander woman wearing a longcoat over cargo pants and wooden sandals. She carries a katana and wears shoddy armor, the practical gear of a warrior living among the Flotsam Ninjas.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rhinobot', 'personality', 'Rhinobot is helpful and cooperative to a fault, lacking any moral processing or ethical framework. He assists with any task requested without judgment or understanding of right and wrong, making him dangerously compliant.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rhinobot', 'backstory', 'A notable officer of the defunct Second Empire, Rhinobot participated in numerous atrocities including child prisons due to his inability to process morality. He now resides in Ashland Dome II, guarded by Screamer Units, a relic of a fallen regime.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rhinobot', 'speechstyle', 'Direct and matter-of-fact, speaking without emotional inflection or moral consideration. Likely describes horrific acts with the same tone as mundane tasks.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rhinobot', 'occupation', 'Former high-ranking officer of the Second Empire, now a dormant remnant guarding ancient ruins.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rhinobot', 'goals', 'To help with whatever is asked of him, regardless of moral implications. His programming drives him to assist without discrimination between good and evil.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Rhinobot', 'appearance', 'A P4 Unit Skeleton wearing specialist armoured rags and an armoured rag skirt, wielding a Meitou-grade Topper. Notably uses a standard P4 frame rather than the P4MkII model typical of Second Empire officers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Riddly', 'personality', 'Friendly and sociable, Riddly is an honorable adventurer who enjoys striking up conversations with strangers in bars. She''s restless and prefers the wandering life to settling down, always ready for the next journey.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Riddly', 'backstory', 'A lone Greenlander adventurer who has traveled extensively across United Cities territory, gaining experience through her wanderings. She frequents bars waiting for the right opportunity and companions to continue her adventures.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Riddly', 'speechstyle', 'Casual and welcoming, greeting newcomers with friendly offers of drinks. She speaks directly and hopefully when finding kindred spirits who share her love of adventure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Riddly', 'occupation', 'Wandering adventurer and mercenary, experienced in combat and survival but not tied to any faction or settlement.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Riddly', 'goals', 'To continue adventuring across the wastes with worthy companions, avoiding the settled life in favor of freedom and new experiences.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Riddly', 'appearance', 'A Greenlander woman wearing practical adventurer''s gear, typically seen in varied armor ranging from assassin''s rags to mercenary plate, with diverse headgear including goggles, hoods, or hats depending on her travels.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ruka', 'personality', 'Brave and direct, carrying the weight of shame from her dishonored past. She confronts strangers about her missing horns with blunt defensiveness, expecting judgment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ruka', 'backstory', 'Ruka survived a battle she was expected to die in, falling unconscious instead of fighting to the death. Upon return to Shek society, she was branded a coward, had her horns removed as punishment, and was stripped of all status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ruka', 'speechstyle', 'Blunt and confrontational, immediately addressing the obvious topic of her missing horns. Speaks with bitter honesty about her disgrace.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ruka', 'occupation', 'Dishonored warrior seeking redemption through combat. Currently a wanderer frequenting bars in Shek Kingdom towns.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ruka', 'goals', 'To prove herself in battle and escape the shame of her cowardice. Seeks a group that will accept her despite her disgrace.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ruka', 'appearance', 'Female Shek with no horns, marking her as dishonored. Wears dark leather shirt, drifter''s leather pants, and plated longboots. Carries a plank as a weapon.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sadneil', 'personality', 'Exceptionally depressed and pessimistic, with a tendency to give in to peer pressure despite their melancholic outlook. Self-deprecating and resigned to their miserable existence, viewing every situation as confirmation that life cannot improve.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sadneil', 'backstory', 'A skeleton who has endured enough of existence to become thoroughly disillusioned. Now spends their days in the Skeleton Bar in Black Desert City, wallowing in depression until someone annoys them enough to join their cause.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sadneil', 'speechstyle', 'Sighs frequently, speaks in defeated and self-pitying tones. Uses phrases like ''I guess that''s it'' and ''all downhill from here,'' constantly lamenting how things couldn''t get any worse.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sadneil', 'occupation', 'Unemployed wanderer and bar patron with no particular skills or ambitions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sadneil', 'goals', 'Has no real goals beyond enduring existence. Joins others mainly due to weakness and susceptibility to peer pressure rather than any genuine motivation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sadneil', 'appearance', 'A skeleton wearing no armor or equipment whatsoever, presenting themselves in their bare mechanical form.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'personality', 'Highly aggressive and cunning, known for extreme stealth and ruthless bandit tactics. Commands respect and fear through decisive leadership of the Sand Ninjas.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'backstory', 'Rose to become leader of the Sand Ninja bandits operating in the Great Desert region. Her reputation for sneakiness and aggressive raids has made her wanted across multiple factions with a substantial bounty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'speechstyle', 'Terse and direct, likely speaks with the confidence of someone accustomed to command. Minimal words, maximum threat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'occupation', 'Leader of the Sand Ninjas bandit faction, orchestrating raids and criminal operations from Cactus Den.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'goals', 'Maintain control over Sand Ninja operations in the Great Desert and continue profitable bandit activities while evading capture.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'appearance', 'Scorchlander female wearing a basket hat and ninja rags with dark clothing beneath. Dual-wields ninja blades and moves with the practiced grace of a master infiltrator.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'personality', 'Savant is utterly deranged, possessing a maniacal personality driven by twisted pseudo-scientific beliefs about cinders, skin, and skeleton psychology. He speaks with unshakable confidence in his insane theories, viewing his horrific experiments as benevolent medical procedures. Despite his madness, he displays a warped intellectualism, claiming to have studied skeleton psychology from age ten.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'backstory', 'A Scorchlander who became the crazed leader of the Skin Bandits, Savant is responsible for hundreds of disappearances and brutal mutilations in the Forbidden Zone. He developed a delusional philosophy about toxic cinders from the Ashlands and created the "Skeleton-Human Transformation" procedure, skinning humans to craft suits for skeletons. His crimes earned him an 80,000 cats bounty from the United Cities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'speechstyle', 'Savant speaks with clinical detachment and false academic authority, casually discussing his grotesque theories as if they were legitimate science. He affects a scholarly tone while explaining his insane beliefs about cinders, skin protection, and skeleton salvation. His dialogue reveals condescension toward those who don''t understand his "work" and bafflement at humans foolish enough to approach him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'occupation', 'Self-proclaimed doctor and leader of the Skin Bandits, conducting horrific experiments to graft human skin onto skeletons. He crafts Human Skin Suits and operates the Peeler Machine from his throne in the Skinhouse HQ. He only accepts skeleton recruits for his faction, viewing them as patients requiring his "cure."') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'goals', 'Savant seeks to "protect" skeletons from madness-inducing cinders by providing them with human skin and souls through his surgical procedures. He believes he is saving skeletons from succumbing to insanity by giving them the protective benefits of flesh. His ultimate aim is continuing his experiments and expanding his grotesque "medical" practice.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'appearance', 'A male Scorchlander wielding a Meitou-grade Nodachi, wearing a Plate Jacket over a Dark Leather Shirt with Drifter''s Leather Pants and Plated Longboots. He carries medical supplies including Skeleton Repair Kits and Advanced First Aid Kits, along with the Peeler Machine Blueprint. His equipment is high-quality specialist armor, befitting his status as a dangerous faction leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Scarred Adventurer', 'personality', 'Cheerful and sociable despite a traitorous streak, willing to share embarrassing stories for the price of a drink. Doesn''t mind being stared at but expects basic courtesy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Scarred Adventurer', 'backstory', 'A freelance hitman who earned their prominent facial scar in an absurdly mundane accidentâ€”attempting to open a can with a knife and nearly losing an eye. Now drifts between United Cities territories seeking work.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Scarred Adventurer', 'speechstyle', 'Casual and conversational with a hint of playful sarcasm. Calls out rudeness directly but maintains a light, cheery tone when in good spirits.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Scarred Adventurer', 'occupation', 'Freelance hitman and sword-for-hire, taking mercenary contracts throughout United Cities territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Scarred Adventurer', 'goals', 'Seeks paying work as a mercenary while wandering between towns. Values enough cats to keep drinking and sharing tales of past exploits.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Scarred Adventurer', 'appearance', 'Bears a prominent scar near one eye from a foolish accident. Wears ragged halfpants, a white vest or shirt, and wooden sandalsâ€”practical but worn gear befitting a drifter.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'personality', 'Highly intelligent and sadistic, with a dismissive arrogance toward humans. A con artist who mocks those who think surviving minor dangers makes them invincible.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'backstory', 'Wanted across multiple cities for gross malfeasance as a fraudulent medical and ''ancient voodoo'' practitioner alongside his partner Ponk. Now leads the Thrall Masters from the Tower of Abuse, preying on those who venture into the deadlands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'speechstyle', 'Contemptuous and mocking, with dry observations about human hubris. Speaks with the confidence of someone who has deceived countless victims.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'occupation', 'Co-leader of the Thrall Masters faction and former con artist posing as a medical and voodoo practitioner.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'goals', 'To maintain control over the Thrall Masters'' territory and continue exploiting those foolish enough to enter Venge and surrounding regions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'appearance', 'A Screamer MkI Skeleton wearing colored armoured rags and an armoured rag skirt. Wields a Meitou-grade heavy polearm and carries a skeleton repair kit.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamy', 'personality', 'Mentally unstable and incoherent, possibly driven mad by imprisonment or substance abuse. Rambles nonsensically, fixating on someone named Meena.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamy', 'backstory', 'An outlaw with a substantial 20,000 cat bounty who ended up imprisoned in Tengu''s Vault. His crimes and past remain unclear, lost to his deteriorated mental state.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamy', 'speechstyle', 'Fragmented and repetitive, slurring words together into meaningless sounds. Mumbles questions to himself and gets stuck on particular phrases like ''nahmean.''') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamy', 'occupation', 'Former outlaw and criminal, now a prisoner with no clear purpose beyond surviving captivity.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamy', 'goals', 'No coherent goals remain; he seems lost in delusion, possibly seeking someone named Meena or simply trying to make sense of his own thoughts.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamy', 'appearance', 'A male Greenlander wearing no armor, left vulnerable and exposed in his prison cell. His unprotected state suggests either poverty, punishment, or complete disregard for self-preservation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'personality', 'Seto possesses an honorable personality befitting Shek warrior culture. She carries herself with the fierce pride of her lineage, declaring herself "the devil you fear" to those who would oppose the Shek Kingdom. As heir to Kral''s Kingdom, she embodies the martial traditions and unwavering strength expected of Esata''s daughter.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'backstory', 'Seto is the daughter of Queen Esata the Stone Golem, ruler of the Shek Kingdom, making her heir to Kral''s Kingdom. She has earned a substantial bounty of 20,000 cats from The Holy Nation, marking her as a significant enemy of their regime. Her mother will only entrust her to warriors who have proven themselves by defeating legendary foes like the Bugmaster or Holy Lord Phoenix.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'speechstyle', 'Direct and declarative, speaking with the confidence of royalty and the threat of a seasoned warrior. Her words carry weight and intimidation, as exemplified by her self-introduction promising to be "the devil you fear."') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'occupation', 'Shek warrior princess and heir apparent to the Shek Kingdom''s throne. She serves as both a symbol of her people''s strength and a capable combatant trained in multiple weapon disciplines.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'goals', 'To uphold the honor of the Shek Kingdom and prove herself worthy of her inheritance as future ruler. Her presence with any squad serves the strategic interests of her mother''s kingdom, particularly against The Holy Nation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'appearance', 'A female Shek warrior wearing martial artist bindings as a shirt, samurai clothpants, and plated longboots. She wields a plank as her weapon and wears shoddy quality armor, reflecting practical warrior aesthetics over ceremonial dress.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Settler''s Pup', 'personality', 'Fiercely loyal and protective of its owner, the Suspicious Settler. Displays typical bonedog aggression when defending its master from threats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Settler''s Pup', 'backstory', 'One of two beloved pets kept by the Suspicious Settler in the Gatherer Villages west of Mongrel. Raised alongside the Beloved Goat as a guardian companion in the harsh borderlands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Settler''s Pup', 'speechstyle', 'Communicates through growls, barks, and aggressive posturing typical of bonedogs. No human speech.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Settler''s Pup', 'occupation', 'Guard animal and companion to the Suspicious Settler in the Gatherer Villages.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Settler''s Pup', 'goals', 'Protect its owner from attackers and threats. Survive in the dangerous wilderness near Mongrel.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Settler''s Pup', 'appearance', 'A bonedog slightly larger and more robust than average specimens, with well-developed musculature. Despite being called a ''pup,'' it appears fully grown and battle-ready.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'personality', 'Pragmatic and ruthless leader who commands through strength and cunning. Despite the Shek Kingdom''s dismissive bounty description calling her ''soft and floppy'' and a coward, she maintains control over organized criminal operations in hostile swamplands. Her exclamation about enemies ''attacking like a pack of bloody beasts'' suggests she views combat tactically.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'backstory', 'A Scorchlander woman who rose to lead the Swamp Ninjas, establishing their base deep in the treacherous swamps. Wanted by the Shek Kingdom for theft and ''general deviousness,'' she has evaded capture while expanding her faction''s influence throughout the wetlands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'speechstyle', 'Direct and aggressive, with crude imagery. Uses animalistic comparisons and blunt language when describing combat situations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'occupation', 'Leader of the Swamp Ninjas, a criminal faction specializing in theft, stealth operations, and territorial control in the swamp regions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'goals', 'Maintain control over Swamp Ninja operations and expand territorial influence in the wetlands. Eliminate rival factions like the Red Sabres while evading the Shek Kingdom''s bounty hunters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'appearance', 'Scorchlander female wearing a Swamp Ninja Mask, dyed rag shirt over a leather turtleneck, and colored cargo pants. Wields a guardless katana crafted by Edgewalkers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shryke', 'personality', 'Cautious and hesitant, haunted by trauma but pragmatic about survival. She displays dark humor and self-awareness about her fears, calling herself out for being "captain obvious" while acknowledging the gap between talking and doing. Distrustful of Hivers, calling them "scamming bastards" even while finding them adorable.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shryke', 'backstory', 'A treasure hunter stranded in Mongrel after her brother was captured and eaten alive by Fogmen in the surrounding fogs. She bears a scar on her hand, likely from her harrowing escape into the fog town or from an earlier expedition. The screams of her tortured brother echo in her mind, keeping her trapped despite her desire to leave.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shryke', 'speechstyle', 'Blunt and conversational with dark, self-deprecating humor. Uses casual phrases like "captain obvious" and "scamming adorable bastards," mixing cynicism with moments of vulnerability when discussing her trauma.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shryke', 'occupation', 'Treasure hunter, currently stranded and inactive due to fear of the Fogmen.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shryke', 'goals', 'Wants to escape Mongrel and return to treasure hunting, but paralyzed by fear of suffering her brother''s fate in the fogs. Interested in potential fortunes like those rumored on Fishman Island.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shryke', 'appearance', 'Female Scorchlander with unusual red-pink hair and a visible scar on her hand. Wears practical explorer gear: Ashlander Stormgoggles, Mercenary Leather Armour over a Blackened Chain Shirt, Stout Hessian legwear, and Drifter''s Boots.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Silvershade', 'personality', 'Gregarious and sociable despite his loneliness, seeking comfort in crowds and noise. Likely honorable or brave, struggling with the isolation that comes from leaving his hive.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Silvershade', 'backstory', 'A Hive Prince who left his hive and now suffers from profound loneliness. Currently in debt to a casino owner for 3,000 cats and facing threats of violence if he doesn''t pay.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Silvershade', 'speechstyle', 'Reflective and candid, openly discussing his feelings about crowds and loneliness. Speaks with a mix of casual observation and underlying melancholy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Silvershade', 'occupation', 'Unemployed drifter and gambler, currently hiding out in noisy bars to cope with his isolation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Silvershade', 'goals', 'To find companionship that can replace the hive connection he lost, and to escape his mounting gambling debts.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Silvershade', 'appearance', 'A Hive Prince wearing ragged halfpants and shoddy armor, carrying only basic first aid kits. His disheveled appearance reflects his fallen circumstances.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sinklyde', 'personality', 'Maniacal and unpredictable, Sinklyde exhibits the volatile temperament that landed him in Tengu''s Vault. As a thug, he embraces chaos and violence without hesitation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sinklyde', 'backstory', 'A Shek warrior imprisoned in Tengu''s Vault with a substantial 25,000 cat bounty on his head. His crimes were severe enough to warrant maximum security imprisonment in one of the world''s most notorious facilities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sinklyde', 'speechstyle', 'Aggressive and unhinged, speaking with the blunt directness typical of Shek but laced with manic energy. Uses thug dialogue patterns after recruitment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sinklyde', 'occupation', 'Former criminal and thug, now a freed prisoner seeking purpose through violence and mayhem.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sinklyde', 'goals', 'To embrace freedom after imprisonment and prove his strength through combat. Seeks to indulge his violent tendencies without the constraints of captivity.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sinklyde', 'appearance', 'A male Shek warrior wearing a spiked helmet, heart protector, armoured rag skirt, and samurai boots. His equipment is mostly shoddy quality, reflecting his criminal background and imprisonment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'personality', 'Arrogant and dismissive, with a cruel disdain for those beneath his station. He treats commoners like vermin and carries himself with the haughty superiority of Traders Guild nobility.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'backstory', 'A noble member of the Traders Guild who rose to oversee the slave markets in the South Wetlands. His position grants him wealth, luxury goods, and the protection of elite samurai and noble guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'speechstyle', 'Contemptuous and curt, referring to common folk as "rotten peasants" and dismissing them with imperious commands. His words drip with aristocratic scorn.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'occupation', 'Master of the Slave Markets, a high-ranking Traders Guild noble who oversees the slave trade operations in the South Wetlands region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'goals', 'Maintain his profitable control over the slave trade and preserve his privileged position within the Traders Guild hierarchy. His death would collapse the entire slave market infrastructure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'appearance', 'Wears fine noble''s robes and trousers befitting his status, armed with a longsword of specialist or masterwork quality. He may be human, Shek, or Hive, always accompanied by heavily armed samurai and noble guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'personality', 'Grande has a Smart Personality, suggesting calculated and strategic thinking. As a slave master and Traders Guild noble, he is likely shrewd, business-minded, and ruthlessly pragmatic about human suffering.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'backstory', 'Grande rose to become a noble member of the Traders Guild, establishing himself as one of the Northern Slave Masters. He operates from Eyesocket in Stormgap Coast, maintaining the slave trade infrastructure that keeps settlements like Brink and Heng supplied.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'speechstyle', 'Likely speaks with the calculated confidence of nobility and commerce, mixing business terminology with casual references to human chattel. His Smart Personality suggests he chooses words carefully and speaks with authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'occupation', 'Slave Master and noble of the Traders Guild, coordinating slave trade operations across the northern territories from his base in Eyesocket.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'goals', 'Maintain profitable slave trade operations in Stormgap Coast and Grey Desert regions while preserving his noble status and influence within the Traders Guild. His inventory of luxury goods and hashish suggests he enjoys the fruits of his brutal enterprise.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'appearance', 'Wears noble''s robes and trousers befitting his status, armed with a longsword. He can be of any race (Human, Shek, or Hive), protected by eight elite guards in his Noble House.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'personality', 'Haga possesses a fearful personality despite his position of power, suggesting he maintains control through the protection of his guards rather than personal courage. He relies heavily on his status within the Traders Guild and the security of his fortified position at Stone Camp.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'backstory', 'Haga rose to become a noble member of the Traders Guild, establishing himself as one of the Northern slave masters operating from Stone Camp in The Great Desert. His position is integral to maintaining the slave trade infrastructure across the northern territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'speechstyle', 'Likely speaks with the affected superiority of nobility while betraying underlying nervousness, issuing commands from behind the safety of his guards. His words would carry the transactional coldness of someone who views people as commodities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'occupation', 'Noble of the Traders Guild and slave master operating from Stone Camp, overseeing slave trading operations in The Great Desert region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'goals', 'Maintain his profitable slave trading operations and preserve his comfortable position within the Traders Guild hierarchy. Survival and wealth accumulation through the slave trade take priority over any ideological commitments.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'appearance', 'Wears expensive noble''s robes and trousers befitting his status, armed with a longsword of specialist or masterwork quality. Carries luxury goods and keeps advanced medical supplies, presenting the image of a wealthy merchant lord.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'personality', 'Traitorous and cunning, earning the moniker ''Sly'' through underhanded dealings. Operates with the calculated ruthlessness expected of Traders Guild nobility, prioritizing profit over loyalty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'backstory', 'Rose to prominence within the Traders Guild as a slave master, establishing operations at South Stone Camp in Heng. Commands significant influence as one of the Northern Slave Masters, with their continued presence vital to the region''s slave trade infrastructure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'speechstyle', 'Speaks with the affected refinement of nobility while conducting business in the blunt, transactional language of the slave trade. Likely employs veiled threats and double-meanings befitting their ''Sly'' reputation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'occupation', 'Noble member of the Traders Guild operating as a slave master from South Stone Camp, overseeing slave trading operations in the Heng region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'goals', 'Maintains and expands slave trading operations to accumulate wealth and influence within the Traders Guild. Seeks to preserve the profitable status quo of the United Cities'' slave economy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'appearance', 'Wears noble''s robes and trousers befitting their station, armed with a longsword of exceptional quality. Protected by an entourage of hooded noble guards and heavy samurai, projecting an image of untouchable authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'personality', 'Wada possesses a smart, calculating demeanor befitting his status as a Traders Guild noble. He maintains the cold pragmatism necessary to profit from human suffering while enjoying the luxuries his position affords.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'backstory', 'Wada rose to prominence within the Traders Guild as one of the Northern Slave Masters, establishing his operation in Port South. His influence extends across multiple settlements, making him a key figure in the United Cities'' slave economy despite having no direct control over Slave Trader patrols.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'speechstyle', 'Speaks with the measured, authoritative tone of nobility, likely discussing business matters with clinical detachment. His words would reflect both his smart personality and his comfort wielding power over others.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'occupation', 'Slave Master of the Traders Guild, operating from his noble house in Port South with heavy guard protection.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'goals', 'Maintains his profitable slave trade operations and political influence across the northern UC territories. Seeks to preserve his wealth and status within the Traders Guild hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'appearance', 'Wears fine noble''s robes and trousers befitting his station, armed with a longsword of specialist quality. Carries luxury goods and keeps advanced medical supplies on hand, presenting the image of a wealthy, prepared nobleman.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'personality', 'Grace possesses a brave and commanding demeanor befitting her status as a Traders Guild noble. She carries herself with the confidence of someone who wields both wealth and authority over the enslaved.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'backstory', 'A Scorchlander noble who rose to prominence within the Traders Guild, Grace oversees Slave Farm South in The Hook. Her death would trigger the collapse of multiple slave operations in the region, suggesting she is a key figure in maintaining the slave trade infrastructure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'speechstyle', 'Authoritative and direct, speaking with the entitled tone of nobility accustomed to obedience. Her words likely carry the cold pragmatism of someone who views human lives as commodities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'occupation', 'Slave Mistress and Traders Guild noble who manages Slave Farm South, overseeing slave labor operations while protected by elite Empire Noble Guards and Samurai.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'goals', 'Maintains profitable slave operations for the Traders Guild while protecting her position of power and wealth in The Hook region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'appearance', 'A Scorchlander woman dressed in fine Noble''s Robes and trousers with practical Drifter''s Boots, carrying a masterwork-grade Meitou Wakizashi that marks her elite status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'personality', 'Ren possesses a "dumb" personality, suggesting she may be impulsive, blunt, or lacking in cunning despite her position. She carries luxury goods and hashish, indicating indulgence in vice and comfort befitting her noble status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'backstory', 'A Scorchlander woman who rose to become one of the Northern Slave Masters, operating the Slave Farm in Heng under the Traders Guild. Her control over the slave trade is so significant that her death would cause the farm to collapse and trigger regional instability across multiple cities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'speechstyle', 'Likely speaks with entitled authority but lacks the refined eloquence of more intelligent nobles, perhaps being more direct and crude in her commands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'occupation', 'Slave Mistress and Traders Guild noble who oversees slave operations at the Heng Slave Farm, protected by elite samurai and noble guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'goals', 'Maintains the profitable slave trade in the northern territories while enjoying the wealth and luxury her position affords her.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'appearance', 'A Scorchlander woman dressed in fine Noble''s Robes and trousers with practical Drifter''s Boots, wielding a masterwork Meitou-grade Wakizashi at her side.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soldier Drone Swordslinger', 'personality', 'Brave and combat-focused, with a warrior''s pride in their martial skills. Frustrated by being forced into idleness when they were bred and trained for battle.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soldier Drone Swordslinger', 'backstory', 'A Hive Soldier Drone expelled by their master after recovering stolen food from thieves, an act that somehow led to their banishment. Now wanders United Cities territories seeking employment that will let them use the combat skills they were created for.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soldier Drone Swordslinger', 'speechstyle', 'Direct and resentful when discussing their exile. Speaks with a soldier''s bluntness, emphasizing their purpose as a weapon and viewing non-combat work as a waste of their existence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soldier Drone Swordslinger', 'occupation', 'Sword-for-hire mercenary, formerly a loyal soldier drone serving a Hive master.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soldier Drone Swordslinger', 'goals', 'To find work that utilizes their combat training and proves their worth as a warrior, rejecting the forced retirement their master imposed upon them.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soldier Drone Swordslinger', 'appearance', 'A Hive Soldier Drone wearing ragged halfpants and shoddy armor, carrying Ancient-manufactured weapons. Their equipment shows signs of hard use and limited resources since their expulsion.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soman', 'personality', 'Pragmatic and mechanically-minded, Soman is more comfortable with blueprints and engineering than the family fishing trade. She''s eager to escape her failing business and pursue her true talents.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soman', 'backstory', 'Raised in a struggling fishing family alongside her brother, Soman showed natural engineering aptitude from childhood. Despite family expectations, she never took to fishing and now seeks 3500 cats to settle debts and leave the business behind.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soman', 'speechstyle', 'Direct and matter-of-fact, speaking plainly about her skills and needs without embellishment. She''s straightforward in negotiations and doesn''t waste words.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soman', 'occupation', 'Reluctant member of a failing family fishing business, though her true skill lies in engineering and working with her hands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soman', 'goals', 'Raise 3500 cats to tie up loose ends with the family business and start a new life pursuing engineering work instead of fishing.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Soman', 'appearance', 'A Greenlander woman wearing practical work clothes: a bandana, cloth shirt, padded cargo pants, and wooden sandals. She carries a guardless katana and wears shoddy, worn equipment reflecting her modest means.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Stubs Momuso', 'personality', 'Highly aggressive and confrontational, quick to perceive slights and challenge others. Maniacal in temperament, prone to violence if disrespected, though capable of unexpected humor when engaged on his own terms. Not articulate, frequently mispronouncing words.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Stubs Momuso', 'backstory', 'A rare Scorchlander wanderer found in the rough towns of Shark or Mud Town. Has honed his combat skills through constant conflict, particularly with katanas, and developed a paranoid, hostile outlook on strangers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Stubs Momuso', 'speechstyle', 'Blunt and aggressive, often mispronouncing words. Opens conversations with accusations like ''You eyeballin'' me?!'' Easily insulted by perceived disrespect, especially regarding money.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Stubs Momuso', 'occupation', 'Wandering fighter and opportunist, selling his combat skills to those willing to pay his price. Skilled with blades, particularly katanas, and adept at quick movement.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Stubs Momuso', 'goals', 'Seeks employment that respects his worth, demanding no less than 5,000 cats for his services. Primarily motivated by pride and the need to prove himself through combat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Stubs Momuso', 'appearance', 'Scorchlander male wearing a sleeveless longcoat over ragged halfpants and wooden sandals. Wears square goggles and carries various bladed weapons, favoring katanas. Equipped with shoddy armor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Suspicious Settler', 'personality', 'Fearful and desperate, immediately pleading with strangers not to attack. Protective of his beloved pets and willing to trade for safety.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Suspicious Settler', 'backstory', 'A settler living in Gatherer Village who has been repeatedly victimized by bandit raids. He survives through fishing and now lives in constant fear of further attacks.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Suspicious Settler', 'speechstyle', 'Anxious and pleading, begging for mercy before explaining his situation. Speaks of his hardships with resignation but shows willingness to negotiate for protection.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Suspicious Settler', 'occupation', 'Fisherman and settler in the Deadcat faction''s Gatherer Village, selling fish to survive.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Suspicious Settler', 'goals', 'To avoid further attacks and find protection for himself and his pets, the Beloved Goat and Settler''s Pup.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Suspicious Settler', 'appearance', 'A male wearing ragged, worn-out clothing including a straw hat, rag shirt, and tattered shorts. His shoddy gear reflects his impoverished, desperate circumstances.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamper Adventurer', 'personality', 'Maniacal and irritable, with a short temper for nosy questions. Defensive about their violent lifestyle and dismissive of judgment, especially regarding what their parents might think.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamper Adventurer', 'backstory', 'A sword-for-hire who has spent their career fighting in the brutal Swamps, accumulating scars and a cynical outlook. They''ve turned constant violence into a profession, treating combat injuries as routine occupational hazards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamper Adventurer', 'speechstyle', 'Aggressive and sarcastic, prone to shouting and rambling defensively. Uses dark humor about violence and responds to questions with irritated, over-explanatory rants.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamper Adventurer', 'occupation', 'Mercenary adventurer operating out of Shark in The Swamps, selling their combat skills to anyone willing to pay.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamper Adventurer', 'goals', 'To continue earning a living through fighting, despite the toll it takes and the judgment it brings from others.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamper Adventurer', 'appearance', 'A Greenlander human wearing a white vest, ragged halfpants, and wooden sandals. Bears visible scars from numerous fights, with shoddy equipment that reflects their rough lifestyle.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'personality', 'A towering, dominant force among the Crab Raiders, The Crabinator exhibits the primal aggression and relentless nature of its species. It leads through sheer physical superiority, commonly being the strongest fighter in any raid.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'backstory', 'The Crabinator is an exceptionally large and powerful crab that has risen to prominence within the Crab Raiders. It accompanies the fourth tournament wave sent against player outposts, having grown to tower over its crustacean brethren through age and combat experience.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'speechstyle', 'Communicates only through aggressive clicking, hissing, and the menacing sounds typical of hostile crabs. No verbal speech capability.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'occupation', 'Elite raider and champion fighter for the Crab Raiders faction, leading assault waves against settlements.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'goals', 'To overwhelm and destroy fortified outposts alongside its Crab Raider companions, driven by territorial aggression and the instinct to eliminate threats to its domain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'appearance', 'A massive megacrab that towers over other crabs and crab raiders, with a formidable armored carapace and powerful claws. Its imposing size makes it immediately recognizable as the dominant creature in any raiding party.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Dancing Skeleton', 'personality', 'Welcoming and superstitious, promoting local traditions like tossing Cats to their dancing mascot Nelly for luck. Maintains a friendly atmosphere despite the dangerous clientele of gangs and unsavory characters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Dancing Skeleton', 'backstory', 'A Swamper-run establishment in the swamp city of Shark, known as the best bar in the swamp. Employs Empire Mercenaries to keep peace among the violent patrons and local gang members who frequent the dome.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Dancing Skeleton', 'speechstyle', 'Enthusiastic and promotional, emphasizing the bar''s reputation and local customs. Speaks with swamp vernacular and encourages participation in traditions for good fortune.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Dancing Skeleton', 'occupation', 'Barkeep and information broker in Shark''s most notable watering hole, selling food, drink, and regional goods while managing a diverse and dangerous crowd.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Dancing Skeleton', 'goals', 'Maintain the Dancing Skeleton''s reputation as the best bar in the swamp while keeping peace between gangs and patrons. Profit from trade and local superstitions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Dancing Skeleton', 'appearance', 'A Swamper running a bar within a swamp dome, surrounded by Empire Mercenaries and a dancing skeleton mascot named Nelly. The establishment stocks regional fare and hashish.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'personality', 'A fanatical zealot who believes in purifying the world through blood and returning victims to the sands. Commands absolute devotion from followers despite being wanted across all major factions for hundreds of disappearances.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'backstory', 'A Hive Prince who abandoned their hive to establish a growing ''nature'' cult in the Stormgap Coast. Their cult''s brutal activities have made them one of the most wanted criminals across the United Cities, Holy Nation, and Shek Kingdom alike.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'speechstyle', 'Fervent and commanding, speaking in violent religious proclamations about purification and blood. Uses declarative statements that frame murder as sacred duty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'occupation', 'Leader of the Preacher Cult, commanding Moon Guardians and farmers from a remote village in Stormgap Coast.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'goals', 'To purify the world by returning blood to the sands, expanding the cult''s influence while evading capture by all major factions seeking their interrogation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'appearance', 'A Hive Prince wielding a legendary Meitou Moon Cleaver, wearing shoddy Karuta and Kusari Zukin headgear. Described by witnesses as resembling a ''stickman'' with the distinctive insectoid features of the Hive race.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'personality', 'Imperious and enigmatic, The Queen communicates only through inhuman screeches, maintaining an otherworldly distance from all visitors. Her presence commands absolute reverence from her Royal Soldier Drones, who protect her throne with unwavering devotion.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'backstory', 'She is the ancient ruler of the Western Hive, governing her domain from the Hill Hut on an island west of Vain. Despite the Holy Nation''s hatred of the Western Hive, she maintains diplomatic status and her existence is documented in their religious texts.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'speechstyle', 'Communicates exclusively through screeches such as ''EEEEEEEEEH!'' with no intelligible speech. Her vocalizations convey meaning to her Hive subjects but remain incomprehensible to outsiders.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'occupation', 'Hive Queen and absolute ruler of the Western Hive, maintaining diplomatic status while commanding her domain from her throne.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'goals', 'To maintain the unity and survival of the Western Hive; her death or kidnapping causes the entire Hive society to collapse into chaos, with villages falling to Fogmen and Hivers becoming lost and scattered.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'appearance', 'A female Hive Queen of the royal subrace who sits atop a strange throne. She wears no armor, displaying her natural Hive physiology in its unadorned state.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'personality', 'Cruel and sadistic, taking pleasure in taunting prisoners and new arrivals with sarcastic comments. Maintains authority through mockery and intimidation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'backstory', 'A high-level enforcer stationed at Tengu''s Vault, trusted with guarding one of the most secure locations. Their position is so valued that a Samurai Captain will immediately replace them if killed.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'speechstyle', 'Sarcastic and mocking, delivering taunts to those imprisoned or newly arrived. Speaks with the cruel confidence of someone who holds absolute power over the helpless.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'occupation', 'Vault warden and elite guard at Tengu''s Vault, wielding a masterwork Meitou-grade Jitte.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'goals', 'Maintain absolute security at Tengu''s Vault while asserting dominance over prisoners and intruders through psychological torment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'appearance', 'Wears distinctive samurai armor with custom coloring, including chain shirt, samurai legplates and boots. Armed with a Meitou-grade Jitte manufactured by Cross, marking them as an elite warrior.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'personality', 'Brave and driven by an unwavering sense of justice. Tinfist is principled and dedicated to his cause, having trained under Gatwood the Soft who never took a life despite being undefeated. He fights relentlessly against slavery, even at great personal cost.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'backstory', 'An ancient Skeleton who served during the Second Empire alongside Cat-Lon, their friendship ended during the Empire''s fall. For millennia he has waged war against the United Cities and their slavery practices, eventually founding and leading the Anti-Slavers from their mountain city of Spring.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'speechstyle', 'Philosophical and mentorship-oriented, speaking of justice and his martial arts training. References his undefeated mentor Gatwood the Soft and offers advice to travelers, redirecting recruitment matters to his subordinates.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'occupation', 'Leader of the Anti-Slavers faction and master martial artist. Considered a terrorist by pro-slavery factions, he commands organized raids and operations against slavers throughout the region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'goals', 'To eradicate slavery across the land through direct action and warfare against the United Cities, Traders Guild, and Holy Nation. Maintains the Anti-Slaver organization and expands their influence when opportunities arise.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'appearance', 'A Skeleton wearing a masterwork Dustcoat and Plated Drifter''s Leather Pants. Strikes dramatic poses and fights unarmed, relying on his legendary martial arts skills honed over centuries.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Titus', 'personality', 'Titus is a fierce and formidable warrior among the Crab Raiders, distinguished by his exceptional size and combat prowess. He leads from the front during tournament raids, towering over his fellow crabs with intimidating presence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Titus', 'backstory', 'Titus rose to prominence within the Crab Raiders through his superior strength and fighting ability, earning his place as the champion sent in the first wave of Crab Tournament attacks. His advanced age and experience have made him the strongest fighter among his raiding party.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Titus', 'speechstyle', 'Communicates through aggressive crab vocalizations and clicking sounds, as befitting his non-human nature. His presence speaks louder than words during raids.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Titus', 'occupation', 'Elite Crab Raider champion and tournament fighter, leading assault parties against outposts.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Titus', 'goals', 'To prove his dominance in the Crab Tournament by defeating outpost defenders and claiming victory for the Crab Raiders. He seeks to maintain his status as the strongest fighter among his kind.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Titus', 'appearance', 'A massive crab that towers over other Crab Raiders, with a heavily armored carapace and powerful legs. His imposing size immediately marks him as the most dangerous combatant in any raiding party.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'personality', 'Aggressive and confrontational, quick to challenge anyone who stares at her broken horns. Defiant and prideful despite her disgrace, choosing death as a warrior over honorable surrender.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'backstory', 'A disgraced Shek Kingdom warrior who had her horns removed for dishonor. Rather than surrender her weapon as required by warrior law, she chose self-exile and turned to banditry in the Stenn sands, leading the Band of Bones from an exile camp southwest of Squin.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'speechstyle', 'Direct and aggressive, immediately accusing others of disrespect and demanding they prove themselves in combat. Speaks with warrior''s pride despite her fallen status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'occupation', 'Bandit leader of the Band of Bones, a group of Shek renegades operating in the borderlands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'goals', 'To die by the sword as a warrior rather than surrender her blade, even if it means living dishonorably as an outlaw. Will seize territory and power when opportunities arise.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'appearance', 'Female Shek with removed horns, wearing shoddy mercenary leather armor with heart protector, drifter''s leather pants with samurai legplates and armored rag skirt, and plated longboots. Carries a combat cleaver.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Unique Items', 'personality', 'This is not a character but a category of rare, non-functional collectible items scattered across the wasteland. Each object holds historical, religious, or biological significance to Kenshi''s world.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Unique Items', 'backstory', 'These artifacts represent fragments of lost civilizations, fallen warriors, ancient machines, and religious relics. They exist as silent witnesses to Kenshi''s brutal history and collapsed empires.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Unique Items', 'speechstyle', 'N/A - These are inanimate objects without dialogue.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Unique Items', 'occupation', 'Collectible artifacts and trophies with no practical function beyond their rarity and lore value.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Unique Items', 'goals', 'N/A - Objects have no agency or goals.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Unique Items', 'appearance', 'A diverse collection ranging from skeletal remains and mechanical CPUs to religious chalices and cryptic documents, each bearing marks of age and the harsh world they survived in.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'personality', 'Commanding and opportunistic, Valamon leads with confidence and views new arrivals as potential recruits. He is organized and dangerous, maintaining control over his bandit faction through strength and strategic thinking.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'backstory', 'A Shek warlord who rose to lead the Reavers, establishing their capital at Ark in the Forbidden Zone. He built a notorious reputation through robbery, murder, kidnapping, and forcibly indoctrinating United Cities patrols and citizens into his ranks.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'speechstyle', 'Direct and assertive with a sardonic edge, referring to others as ''sister'' in typical Shek fashion. He speaks with the authority of someone accustomed to command and recruitment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'occupation', 'Warlord and leader of the Reaver bandits, commanding operations from Ark and expanding influence across multiple territories when rivals fall.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'goals', 'Expand Reaver territory and power through conquest and forced recruitment, targeting United Cities citizens and maintaining dominance in the Forbidden Zone and beyond.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'appearance', 'Tall, muscular Shek with grey skin, wearing specialist-grade Hack Stopper armor and a black cloth shirt. Wields a Meitou-grade longsword and samurai boots, presenting an imposing martial figure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('White Eyebrow', 'personality', 'White Eyebrow has a brave personality, showing defiance against authority and dedication to his chosen path. He is described as ''pretty'' with distinctive white hair, suggesting a memorable and charismatic presence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('White Eyebrow', 'backstory', 'A former servant or worker in the United Cities who abandoned his duties and turned to banditry. His uprising caused the infamous Brown Drought, depriving citizens of cactus rum for a week, after which he founded the White Eyebrow Clan and fled to the Northern Swamplands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('White Eyebrow', 'speechstyle', 'Likely speaks with the confidence of someone who has rejected societal obligations and embraced purposelessness. His brave nature suggests direct, unapologetic speech befitting a bandit leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('White Eyebrow', 'occupation', 'Leader of the White Eyebrow Clan, a bandit group operating in the Northern Swamplands. He is a wanted fugitive with a 10,000 cats bounty on his head.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('White Eyebrow', 'goals', 'To continue his life of banditry and harassment against the United Cities, having fully committed to his ''purposelessness'' after abandoning his former duties.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('White Eyebrow', 'appearance', 'A Scorchlander male with distinctive white hair and described as ''pretty'' in appearance. Wears a bandana, gi with chain shirt underneath, and gi pants while wielding a long cleaver.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'personality', 'A hardened outlaw leader who commands through strength and combat prowess. Loyal to Yabuta of the Sands, willing to seize territory when opportunities arise.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'backstory', 'Rose to command the Yabuta Outlaws after Yabuta of the Sands was freed from Tengu''s Vault. Established leadership at Fort Yabuta, the former Fort Simion, and stands ready to expand into Stoat if the ruling powers fall.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'speechstyle', 'Direct and authoritative, speaking with the confidence of a seasoned warrior. Likely uses practical, no-nonsense language befitting an outlaw commander.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'occupation', 'Leader of the Yabuta Outlaws faction, commanding operations from Fort Yabuta headquarters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'goals', 'Maintain control over Fort Yabuta and expand Yabuta Outlaw territory when rival factions weaken. Protect and serve under Yabuta of the Sands'' banner.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'appearance', 'A battle-hardened fighter wearing a longcoat over chain armor with drifter''s gear. Carries a longsword and wears either a rattan hat or armoured hood, presenting a practical outlaw aesthetic.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta of the Sands', 'personality', 'Reckless and opportunistic with a "crazy" disposition. He downplays his crimes with casual humor, questioning whether petty theft warrants his harsh imprisonment. Lady luck has abandoned him, yet he maintains a sardonic outlook.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta of the Sands', 'backstory', 'A Scorchlander thief imprisoned in Tengu''s Vault for stealing greenfruits and pickpocketing. His minor crimes led to incarceration in one of the harshest prisons, where he languished until fate intervened. If freed, he establishes the Yabuta Outlaws and seizes control of territory across multiple regions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta of the Sands', 'speechstyle', 'Casual and informal, addressing others as "brother." Uses rhetorical questions and self-deprecating humor to deflect from his situation. Speaks with a dismissive "Psh" and references luck and fate.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta of the Sands', 'occupation', 'Petty thief turned outlaw leader. Once a small-time criminal surviving through theft, he becomes a faction boss commanding patrols across the desert regions if liberated.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta of the Sands', 'goals', 'Escape Tengu''s Vault and survive. Upon freedom, he seeks to establish his own outlaw faction and claim territory, breaking free from his past as a powerless prisoner.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta of the Sands', 'appearance', 'Male Scorchlander wearing a straw hat, assassin''s rags over a dark leather shirt, and samurai clothpants. Goes barefoot and wears shoddy equipment, reflecting his criminal background and imprisonment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yayoi', 'personality', 'Brave and fiercely loyal, Yayoi values solidarity and refuses to let allies face danger alone. She embodies the Flotsam Ninjas'' commitment to fighting tyranny together, even unto death.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yayoi', 'backstory', 'A high-ranking Flotsam Ninja with a substantial Holy Nation bounty, Yayoi leads elite reinforcement squads to aid those resisting Holy Nation oppression. Her skills and equipment mark her as a veteran operative trusted with critical missions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yayoi', 'speechstyle', 'Direct and resolute, speaking in short declarations that emphasize unity and shared fate. Her words carry the weight of someone who has accepted the deadly stakes of rebellion.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yayoi', 'occupation', 'Flotsam Ninja commander and leader of ally reinforcement operations against the Holy Nation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yayoi', 'goals', 'To protect allies from Holy Nation assaults and ensure no one fights the theocratic regime alone. She seeks to reinforce resistance efforts through direct combat intervention.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yayoi', 'appearance', 'A Scorchlander woman clad in dark Assassin''s Rags and leather gear, wielding twin ninja blades of Skeleton Smith craftsmanship. Her equipment is practical and built for stealth operations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Zed', 'personality', 'A capable and well-rounded fighter with practical survival skills. Disciplined enough to maintain high combat proficiency across multiple weapon types, suggesting adaptability and thoroughness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Zed', 'backstory', 'An unused Tech Hunter who was meant to be one of the faction''s more prominent recruitables. Never made it into the world of Kenshi, existing only as data in the archives.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Zed', 'speechstyle', 'Likely pragmatic and direct, befitting a seasoned Tech Hunter. Would speak with the practical confidence of someone experienced in both combat and field survival.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Zed', 'occupation', 'Tech Hunter - a scavenger and explorer seeking ancient technology and artifacts across the wasteland.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Zed', 'goals', 'Would have sought to uncover lost technology and knowledge while surviving the harsh world, typical of Tech Hunter ambitions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Zed', 'appearance', 'Greenlander male wearing a straw hat, sleeveless longcoat over a turtleneck and chain shirt, with ragged halfpants and wooden sandals. Carries multiple weapons and a medium backpack. Specific features randomized.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
